export const PROPOSICOES_SEED = [{"proposicao":"5/2026","tipo":"REQ","casa":"CN","ementa":"Requer a realização de audiência pública com o Excelentíssimo Ministro de Estado da Defesa, com o objetivo de debater as perspectivas de financiamento das políticas de defesa nacional, a execução orçamentária dos programas e investimentos sob responsabilidade da Pasta, bem como as prioridades governamentais voltadas ao preparo e emprego das Forças Armadas, à proteção das fronteiras, ao desenvolvimento da Base Industrial de Defesa, à segurança cibernética e espacial, e ao fortalecimento da soberania nacional.","autor":"Dep Domingos Neto (PSD/CE)","relator":"","impacto":"Presença do Mininstro da Defesa e possivelmente do Cmt Ex.","tramitacao":"22/06/2026 - Em tramitação na CMO.\n23/06/2026 - Aprovada na CMO, aguardando audiência pública.","atuacao":"Acompanhar","percepcao":"Designado assessor: Maj Torres","status":"atencao","assessor":"Maj Torres","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/174832"},{"proposicao":"21/2026","tipo":"REQ","casa":"CN","ementa":"Requer a realização de Audiência Pública destinada a debater o tema: “Projeto de Desenvolvimento e Programa de Aceleração do Crescimento (PAC) frente aos desafios fiscais da economia nacional.","autor":"Deputado Federal Inácio Arruda (PCdoB/CE)","relator":"","impacto":"Os projetos estratégicos do Exército fazem parte do Novo PAC. Acompanhar a audiência para verificar possíveis menções aos nossos programas.","tramitacao":"22/06/2026 - Em tramisão na CMO.\n23/06/2026 - Aprovada na CMO, aguardando audiência pública.","atuacao":"Acompanhar","percepcao":"Designado assessor: Maj Torres","status":"atencao","assessor":"Maj Torres","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/174849"},{"proposicao":"2/2026","tipo":"PLN","casa":"CN","ementa":"Dispõe sobre as diretrizes para a elaboração e a execução da Lei Orçamentária de 2027 e dá outras providências.","autor":"Poder Executivo","relator":"","impacto":"O EME se posiciona favorável ao PLDO/2027 por manter a coerência com o ordenamento orçamentário em vigor, preservando instrumentos relevantes para a área de Defesa e por não apresentar, no que concerne aos interesses institucionais do Exército, óbices materiais que justifiquem oposição à sua tramitação.","tramitacao":"15/04/2026 - Recebida a Mensagem Presidencial\n16/04/2026 - Matéria aguarda despacho do Presidente do Congresso Nacional para envio à CMO.","atuacao":"Acompanhar.\nFoi sugerida pela Subassessoria de Orçamento/A4 ao EME, uma emenda ao texto para impedir o bloqueio dos recursos vinculados à LC 221/2025 (5 bilhões por ano até 2030).","percepcao":"Designado assessor: Maj Torres","status":"atencao","assessor":"Maj Torres","link":"https://www.congressonacional.leg.br/web/orcamento/acompanhe/diretrizes-orcamentarias/-/ldo/2027"},{"proposicao":"18/2026","tipo":"PLN","casa":"CN","ementa":"Altera o art. 4º da Lei nº 15.346, de 14 de janeiro de 2026, que estima a receita e fixa a despesa da União para o exercício financeiro de 2026.","autor":"Poder Executivo","relator":"","impacto":"Projeto de Lei do Congresso Nacional (PLN) nº 18, de 2026, a proposta altera o art. 4º da Lei nº 15.346/2026 (LOA 2026) e traz um impacto estratégico direto para o setor de Defesa Nacional e, consequentemente, para as Força Armadas. O principal impacto ocorre por meio da inclusão da alínea \"g\", ao inciso II, do § 1º, do art. 4º da LOA 2026. Abaixo, segue o detalhamento das implicações dessa medida:​\n\n1. Flexibilização de Créditos para Projetos Estratégicos de Defesa​\n O art. 4º da Lei Orçamentária Anual (LOA) define os limites e as condições para a abertura de créditos suplementares e remanejamentos de dotações. Ao incluir os projetos estratégicos em defesa nacional nesse rol, o PLN 18/2026 permite maior agilidade e flexibilidade no manejo orçamentário de ações voltadas à modernização e ao reaparelhamento das Forças Armadas. ​\n\n2. Alinhamento com a Lei Complementar nº 221/2025​\n A exposição de motivos (EXM nº 1340/2026) deixa claro que a medida visa adequar a execução do orçamento às diretrizes da Lei Complementar nº 221, de 18 de novembro de 2025. Como essa LC foi promulgada após o envio do Projeto de Lei Orçamentária (PLOA) de 2026 ao Congresso Nacional, as Forças Armadas careciam de um mecanismo regulatório na LOA em curso para executar esses recursos em sua plenitude. O PLN corrige esse descasamento temporal legislativo.​\n\n3. Proteção e Continuidade de Programas de Alto Impacto​\n Diferente de despesas correntes ordinárias, os projetos estratégicos da Defesa (como o Programa de Desenvolvimento de Submarinos - PROSUB, a aquisição dos caças Gripen, ou o Blindado Guarani) operam em ciclos plurianuais complexos e dependem de fluxos financeiros previsíveis. A alteração confere segurança jurídica para remanejamentos que evitem a paralisia dessas linhas de desenvolvimento por amarras fiscais rígidas no âmbito do Ministério da Defesa. ​\n\n​Conclusão​\nO PLN 18/2026 não cria, por si só, novos recursos (espaço fiscal ou novas receitas) para a Defesa, mas dota o Ministério da Defesa e os Comandos Militares da discricionariedade e flexibilidade necessárias para suplementar e remanejar dotações internamente voltadas a projetos estratégicos, alinhando a execução orçamentária de 2026 com o novo arcabouço da recém-aprovada Lei Complementar nº 221/2025.​","tramitacao":"17/06/2026 - Recebida a Mensagem Presidencial\n17/06/2026 - Matéria aguarda despacho do Presidente do Congresso Nacional para envio à CMO.","atuacao":"Acompanhar.\nPossível atuação para fazer a relatoria.","percepcao":"","status":"atencao","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/174743"},{"proposicao":"51/2025","tipo":"VET","casa":"CN","ementa":"Veto parcial aposto ao Projeto de Lei do Congresso Nacional nº 2, de 2025, que \"Dispõe sobre as diretrizes para a elaboração e a execução da Lei Orçamentária de 2026 e dá outras providências\".","autor":"PR","relator":"","impacto":"","tramitacao":"2/ 01 - Mesa - Mesa Diretora do Congresso Nacional\n- Recebimento no Congresso Nacional: 02/01/2026\n- Sobrestando a pauta a partir de: 04/03/2026","atuacao":"Acompanhar","percepcao":"Designado assessor: Maj Torres","status":"atencao","assessor":"Maj Torres","link":"https://www.congressonacional.leg.br/materias/vetos/-/veto/detalhe/17909"},{"proposicao":"9/2026","tipo":"VET","casa":"CN","ementa":"Veto parcial aposto ao Projeto de Lei do Congresso Nacional nº 15, de 2025, que \"Estima a receita e fixa a despesa da União para o exercício financeiro de 2026\".","autor":"PR","relator":"","impacto":"","tramitacao":"20/01 - Mesa Diretora do Congresso Nacional - PRONTO PARA DELIBERAÇÃO DO PLENÁRIO\n02/02 - Anexada a Nota técnica Conjunta - Vetos ao Projeto de Lei Orçamentária para 2026","atuacao":"Acompanhar","percepcao":"Designado assessor: Maj Torres","status":"atencao","assessor":"Maj Torres","link":"https://www.congressonacional.leg.br/materias/vetos/-/veto/detalhe/17909"},{"proposicao":"204/2025","tipo":"PLP","casa":"CD","ementa":"Estabelece programação orçamentária não sujeita às metas fiscais, desvincula recursos, e veda limitação de empenho em projetos estratégicos para a Defesa Nacional.","autor":"Senador Carlos Portinho (PL/RJ)","relator":"","impacto":"O PLP 204/2025 gera benefícios imediatos ao criar uma margem fiscal anual de até R$ 5 bilhões fora do limite da LC 200/2023 e da meta de primário, vinculando 40% desses recursos a investimentos e exigindo conteúdo nacional mínimo de 35%, o que qualifica o gasto e estimula a Base Industrial de Defesa. Todavia, sua temporalidade (2026–2031) e teto nominal contrastam com a ambição da PEC 55/2023, que buscava institucionalizar 2% do PIB como piso para a Defesa. Esse descompasso pode produzir efeito substitutivo: o PLP resolve parcialmente a questão no curto prazo, mas tende a reduzir a pressão política por uma solução estrutural e duradoura, perpetuando o risco de subfinanciamento crônico da Defesa no médio e longo prazo.","tramitacao":"29/09 - Plenário do Senado Federal\n22/10/25 - Aprovada em Plenário do Senado Federal\n27/10/25 - Remetida à Câmara dos Deputados\n19/11/2025 -Transformada em noma jurídica (Lei 221/2025)","atuacao":"Acompanhar","percepcao":"- Designado assessor:","status":"concluida","assessor":"","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/170654"},{"proposicao":"15/2025","tipo":"PLN","casa":"CN","ementa":"258","autor":"PR","relator":"","impacto":"- A LOA é vital para o funcionamento eficiente, o planejamento estratégico e a prestação de contas do Exército, pois: define os recursos disponíveis para o EB, permitindo um planejamento eficiente de suas atividades, treinamentos e aquisições de equipamentos; assegura o financiamento contínuo para projetos e operações de longo prazo, permitindo que o EB mantenha sua eficiência e estado de prontidão; e estabelece um limite de despesas para o Exército, ajudando a manter o controle financeiro e evitando gastos excessivos.\n- A tramitação do PLOA no Congresso Nacional requer muita atenção, tendo em vista que podem ocorrer cortes na proposta encaminhada pelo Executivo e mudanças nas prioridades. Essas alterações podem afetar a sustentabilidade dos meios militares e, consequentemente, o estado de prontidão permanente, bem como o processo de transformação da Força Terrestre, por meio da continuidade dos Projetos Estratégicos do Exército.","tramitacao":"29/08 - Mesa Diretora CN: Recebida a Mensagem Presidencial nº 1.214/2025 \n1/09 - Recebida na CMO: Relator: DF ISNALDO BULHÕES JR.\n02/09 - CMO: designado como Relator Setorial de Defesa o Sen Esperidião Amin (PP-SC).\n16/12 - CMO: Publicação e Votação do Relatório Geral na CMO.\n19/12/25 - Aprovado o substitutivo em Plenário do Congresso Nacional \n15/01/25 - Transformada em norma jurídica com veto parcial do presidente da república (Lei 15346/2026).","atuacao":"- Encaminhar o Projeto apresentado à 6ª SCh/EME para verificar se as demandas apresentadas pela Força ao Governo foram contempladas.\n- Acompanhar a tramitação do projeto no CN, com atenção para apresentação de emendas e pareceres.\n- Caso as demandas da Força não tenham sido atendidas na apresentação do projeto, atuar junto ao relator ou a outros parlamentares para emendar o texto.\n- Atuar na captação de recursos por meio de emendas ao PLOA, sensibilizando os parlamentares sobre as necessidades financeiras e estratégicas do EB, fornecendo informações técnicas e justificativas que embasem a alocação de recursos adicionais.\n- Manter um diálogo aberto e frequente com parlamentares para explicar as necessidades e prioridades orçamentárias do EB.\n- Fornecer informações técnicas para ajudar os legisladores a entender o impacto de diferentes níveis de financiamento nas operações do EB.\n- Defender a alocação de recursos que estejam alinhados com as metas e necessidades estratégicas do EB, incluindo a manutenção de equipamentos, treinamento de pessoal, e outros projetos prioritários.\n- Trabalhar em sintonia com outros setores da Força para garantir que as informações e demandas enviadas ao legislativo sejam precisas e coerentes.","percepcao":"#NAME?","status":"concluida","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/170202"},{"proposicao":"163/2025","tipo":"PLP","casa":"SF","ementa":"Altera a Lei Complementar nº 200, de 30 de agosto de 2023, para excluir do cômputo dos limites de despesas primárias as despesas temporárias com educação pública e saúde de que trata o art. 6º da Lei nº 15.164, de 14 de julho de 2025, e as despesas financiadas com recursos oriundos de empréstimos internacionais e suas respectivas contrapartidas, bem como excluir as referidas despesas com educação pública e saúde das metas fiscais, e dá outras providências.","autor":"Dep Isnaldo Bulhões Jr. - MDB/AL","relator":"","impacto":"O Parecer nº 23-2025-SPAE/6ª SCh EME avaliou o PLP nº 163/2025 e concluiu que, na forma original, a proposta é desfavorável ao Exército. O documento reconhece que a exclusão do teto fiscal para despesas com educação, saúde e empréstimos internacionais beneficia a FAB (Gripen, KC-390) e a Marinha (PROSUB), mas ressalta que o Exército não possui projetos financiados por crédito externo, o que o deixaria proporcionalmente mais exposto a bloqueios e contingenciamentos. O parecer também adverte que a emenda da Aeronáutica, ao incluir despesas com acordos de transferência de tecnologia, reforçaria a proteção orçamentária da FAB, mas acentuaria o desequilíbrio interno, concentrando restrições na Força Terrestre. Diante disso, o EME defendeu a adoção do substitutivo do Ministério da Defesa, já debatido entre as três Forças, que propõe a exclusão do teto para todos os projetos estratégicos de Defesa (RP3), o uso do superávit de alienação de imóveis militares, a fixação de piso mínimo anual para RP3 e a vedação ao contingenciamento, garantindo uma solução mais equilibrada, sistêmica e favorável à modernização do Exército Brasileiro.","tramitacao":"14/08/2025 - Mesa Diretora CD: Apresentação de Requerimento de Urgência pelos Deputado José Priante (MDB/PA) e outros.\n15/12/2025 - Aprovada a redação final em Plenário.\n19/12/2025 - Transformada em norma jurídica (Lei Complementar 223/2025).","atuacao":"Acompanhar","percepcao":"Além de excluir do limite fiscal as despesas financiadas com empréstimos internacionais e suas contrapartidas, como propõe o PLP nº 163/2025, a FAB apresentou uma emenda propondo ampliar essa proteção para incluir também os acordos e contratos internacionais com transferência de tecnologia, como o caso do Gripen. O texto ainda autoriza que o superávit financeiro dos fundos de Defesa (Exército, Aeronáutico e Naval), tradicionalmente destinados ao reaparelhamento militar, seja aplicado diretamente em projetos estratégicos da área de Defesa, impedindo que esses recursos sejam desviados para o pagamento da dívida pública, como previsto na LC nº 211/2024. A emenda também garante que os recursos de financiamentos externos (Fonte 1449) possam ser inscritos em Restos a Pagar, assegurando a execução de contratos de longo prazo. Assim, complementa o PLP ao devolver às Forças Armadas autonomia e previsibilidade sobre seus fundos e a continuidade de programas estratégicos como Gripen, KC-390, PROSUB, Guarani e SISFRON.\n- Designado assessor:","status":"concluida","assessor":"","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2541109"},{"proposicao":"1309/2025","tipo":"MPV","casa":"CN","ementa":"Institui, no âmbito do Poder Executivo federal, o Plano Brasil Soberano e o Comitê de Acompanhamento das Relações Comerciais com os Estados Unidos da América,","autor":"Poder Executivo","relator":"","impacto":"A medida institui o Plano Brasil Soberano e o Comitê de Acompanhamento das Relações Comerciais com os Estados Unidos. Ela altera diversas leis para apoiar exportadores brasileiros afetados por tarifas adicionais impostas pelos EUA. As ações incluem apoio financeiro, prorrogação de prazos tributários, e medidas para facilitar a aquisição de produtos não exportados.","tramitacao":"15/08: Mesa Diretora CN: Despachada à CMO.\n11/12/2025 - Sem eficácia por não ter sido votada no prazo de 120 dias.","atuacao":"Acompanhar","percepcao":"","status":"concluida","assessor":"","link":"https://www.congressonacional.leg.br/materias/medidas-provisorias/-/mpv/169893"},{"proposicao":"156/2025","tipo":"PLP","casa":"CD","ementa":"Altera a Lei Complementar nº 210, de 25 de novembro de 2024 para dispor sobre os limites das emendas parlamentares aos projetos de lei orçamentária anual.","autor":"Dep Tabata Amaral - PSB/SP","relator":"","impacto":"Propõe limitar o crescimento das emendas parlamentares ao Orçamento da União, adotando como referência os valores aprovados na LOA de 2016, corrigidos apenas pelo teto de gastos (no caso das emendas impositivas) ou pelo IPCA (para as não impositivas). Atualmente, esses valores crescem em função da arrecadação e do limite de despesa primária, o que resultou em um volume expressivo de R\\$ 50,3 bilhões em 2025, comprometendo o espaço fiscal do governo. A proposta busca conter esse crescimento automático, preservar recursos discricionários para políticas públicas e reforçar o equilíbrio fiscal. Para o Exército, a aprovação do PLP nº 156/2025 tende a ser positiva, ao aliviar a pressão sobre o orçamento discricionário e ampliar o espaço fiscal para alocações estratégicas definidas pelo Executivo. Embora possa haver redução nos recursos oriundos de emendas, a medida favorece maior previsibilidade orçamentária e continuidade dos programas estruturantes da Força.","tramitacao":"21/07 Mesa Diretora: apresentada.","atuacao":"Acompanhar","percepcao":"- Designado assessor: TC Alessandra","status":"interesse","assessor":"TC Alessandra","link":"http://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2538380&fichaAmigavel=nao"},{"proposicao":"44/2024","tipo":"PEC","casa":"CD","ementa":"Altera o §9º do artigo 166 da Constituição Federal para destinar parte (3%) dos recursos oriundos das emendas individuais a programas e ações relacionados ao Esporte.","autor":"Douglas Viegas - UNIÃO/SP , Célio Studart - PSD/CE , Flávia Morais - PDT/GO e outros","relator":"","impacto":"O projeto propõe alterar a Constituição Federal para obrigar que 3% das emendas parlamentares individuais sejam destinadas especificamente a programas e ações relacionados ao esporte. Essa mudança poderá impactar indiretamente o Exército, uma vez que reduzirá a flexibilidade dos parlamentares para destinar recursos a outras áreas, possivelmente diminuindo o volume de emendas tradicionalmente direcionadas a programas militares e aumentando a concorrência pela captação desses recursos. Tal cenário exigirá maior articulação política da Instituição para preservar suas demandas orçamentárias. Por outro lado, a proposta também abre uma oportunidade para o Exército acessar esses novos recursos, o que provavelmente demandará a criação de uma ação orçamentária específica que caracterize formalmente a aplicação dos valores em programas esportivos nas Forças Armadas.","tramitacao":"10/04/2025 - CCJC :Apresentação do PRL n. 1 CCJC (Parecer do Relator), pela Dep Laura Carneiro (PSD/RJ) pela admissibilidade.","atuacao":"Acompanhar.","percepcao":"","status":"interesse","assessor":"","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2471383"},{"proposicao":"1/042025","tipo":"PLN","casa":"CN","ementa":"Altera a Lei nº 15.080, de 30 de dezembro de 2024 (LDO 2025), que dispõe sobre as diretrizes para a elaboração e a execução da Lei Orçamentária de 2025.","autor":"Poder Executivo","relator":"","impacto":"A proposição, a princípio, não gera impacto direto para o Exército, pois trata exclusivamente da flexibilização de repasses do Ministério da Saúde a entidades civis sem fins lucrativos vinculadas ao SUS, sem alterar normas orçamentárias que envolvam o MD. No entanto, pode haver impactos indiretos para o LQFEx, o IME, o IBEx e o HFA, que atuam em pesquisa, desenvolvimento tecnológico e apoio a ações de saúde pública. A mudança pode facilitar parcerias e convênios em áreas de interesse estratégico, como defesa biológica, produção de insumos e logística em regiões remotas, favorecendo a integração com o Complexo Econômico-Industrial da Saúde.\nEME: parecer indiferente PLN nº 4/2025, uma vez que a proposta de alteração não se insere no escopo de competências da Força e não acarreta repercussões negativas ao EB.","tramitacao":"23/06 Mesa Diretora CN: Recebida Msg Presidencial nº 743/2025. A matéria aguarda despacho do Presidente do CN para envio à CMO.","atuacao":"Matéria enviada ao EME para análise.\nAcompanhar tramitação na CMO e CN.\n23/12/2025 - Transformada em norma jurídica.","percepcao":"- Designado assessor: Maj Pires","status":"concluida","assessor":"Maj Pires","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/169260"},{"proposicao":"1/022025","tipo":"PLN","casa":"CN","ementa":"PLDO 2026: Dispõe sobre as diretrizes para a elaboração e a execução da Lei Orçamentária de 2026 e dá outras providências.","autor":"Poder Executivo","relator":"","impacto":"A LDO estabelece metas e prioridades da administração pública federal, condicionando a alocação de recursos e impactando diretamente a capacidade do Exército de executar despesas discricionárias, realizar investimentos, promover concursos e implementar projetos estratégicos.\nO EME concluiu que o PLDO/2026 não traz inovações relevantes nem impactos negativos ao EB, emitindo parecer favorável à sua tramitação. Contudo, sugeriu duas emendas, visando resguardar os recursos destinados aos Projetos Estratégicos da Força contemplados pelo Novo PAC (Av Ex, F Bld, ASTROS e SISFRON): 1. Inserir os recursos destinados aos referidos projetos em um rol de despesas ressalvadas, no Anexo III; 2. Suprimir o inciso XIII do Art 74, que limita a execução a 1/12 das despesas do Novo PAC, caso a LOA 2026 não seja publicada até 31 DEZ 2025.","tramitacao":"15/07 CMO:\n- Aprovado o Relatório Preliminar.\n- Proposta de cronograma no 2º Semestre:\n Emendas ao projeto: 05 a 14/08\n Apresentação do Relatório Final: 22/08\n Votação do Relatório Final na CMO: 27/08.\n03/12/2025 - Aprovado o substituto no plenário do CN.\n02/01/2026 - Transformada em norma jurídica (Lei 15321/2025).","atuacao":"- Acompanhamento da apresentação dos relatórios e de emendas, atuando junto ao relator para manutenção dos interesses da Força.","percepcao":"O PLDO 2026 revela um cenário fiscal crítico até 2029, com o avanço das despesas obrigatórias, o aumento dos precatórios, o grande volume de emendas impositivas — reflexo do empoderamento do Legislativo sobre o orçamento — e um arcabouço que autoriza crescimento real das despesas acima da inflação, independentemente da arrecadação. Esse conjunto pressiona fortemente o espaço fiscal, comprimindo as despesas discricionárias, que vão ficar abaixo de R$ 70 bi em 2027 — valor insuficiente para manter a máquina pública, com risco real de shutdown. Para o Exército, isso compromete operações, contratos estratégicos e a capacidade de pronta resposta, além de acentuar debates sobre o Sistema de Proteção Social das Forças Armadas (SPSMFA), pois os gastos previdenciários, por estarem indexados ao aumento do salário mínimo, pressionam cada vez mais as contas públicas.","status":"concluida","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/168120"},{"proposicao":"1466/2025","tipo":"PL","casa":"CD","ementa":"Reestruturação de Carreiras e Ajustes Salariais no Poder Executivo Federal","autor":"Poder Executivo","relator":"","impacto":"No texto final, aprovado no Senado, foi suprimido o Inciso I do Art. 213, que extinguia a gratificação de representação de função de gabinete militar de que tratam a Lei nº 8.460, de 17 de setembro de 1992, e a alínea “g” do Anexo III à Lei nº 11.526, de 4 de outubro de 2007.","tramitacao":"02/04 - Mesa Diretora CD: apresentação.\n26/05/2025 Apresentação do autógrafo.\n28/05/2025 PLEN - Plenário do Senado Federal. Situação: APROVADA\n03/06/2025 SF-SEXPE - Secretaria de Expediente Situação: TRANSFORMADA EM NORMA JURÍDICA\nAção: (PR) PRESIDÊNCIA DA REPÚBLICA. SANCIONADA. LEI 15141 DE 2025.","atuacao":"Acompanhar","percepcao":"- Designado assessor: Cel Sidnei Viana","status":"concluida","assessor":"Cel Sidnei Viana","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2494408"},{"proposicao":"1293/2025","tipo":"MPV","casa":"CN","ementa":"Soldos dos militares das Forças Armadas.","autor":"Poder Executivo","relator":"","impacto":"Reajustar os soldos dos militares, alterando a lei nº 13954, de 16 de dezembro de 2019.","tramitacao":"18/07/2025 SF-SEXPE: PROMULGADA. LEI N° 15167 DE 2025.","atuacao":"Acompanhar","percepcao":"","status":"concluida","assessor":"","link":"https://www.congressonacional.leg.br/materias/medidas-provisorias/-/mpv/167786"},{"proposicao":"1286/2025","tipo":"MPV","casa":"CN","ementa":"Reestruturação de Carreiras e Ajustes Salariais no Poder Executivo Federal","autor":"Poder Executivo","relator":"","impacto":"Art. 213. Ficam extintas: I - a gratificação de representação de função de gabinete militar de que tratam a Lei nº 8.460, de 17 de setembro de 1992, e a alínea “g” do Anexo III à Lei nº 11.526, de 4 de\noutubro de 2007.","tramitacao":"31/12/2024 - Mesa Diretora do Congresso Nacional: apresentação.\n- Deliberação da Medida Provisória: de 03/02/2025 a 03/04/2025.\n11/02/2025 - CMMPV 1286/2024: Encerrado o prazo regimental, foram apresentadas 517 emendas.\nÚltimo estado: AGUARDANDO DESIGNAÇÃO MEMBROS COMISSÃO.\nSituação: 03/06/2025 - SEM EFICÁCIA.","atuacao":"Acompanhar","percepcao":"","status":"concluida","assessor":"","link":"https://www.congressonacional.leg.br/materias/medidas-provisorias/-/mpv/166962"},{"proposicao":"1/012025","tipo":"PRN","casa":"CN","ementa":"Altera disposições da Resolução n° 1, de 2006-CN, para adequar o rito de apresentação e indicação de emendas parlamentares.","autor":"Mesas do Senado Federal e da Câmara dos Deputados","relator":"","impacto":"Maior transparência no rito de emendas pode reduzir a flexibilidade do Exército na gestão de recursos, enquanto a burocracia adicional pode atrasar a execução orçamentária e impactar projetos estratégicos.\nExcepcionalmente, a CMO instalada em 2024 terá seu mandato prorrogado até a votação do relatório geral do PLOA 2025, quando será instalada a nova comissão.","tramitacao":"12/03 Mesa Diretora do Congresso Nacional: Autuado o Projeto de Resolução nº 1/2025. O projeto vai à publicação.\n13/03 Mesa Diretora do Congresso Nacional: Aprovada. A matéria vai à promulgação.\n14/03 Mesa Diretora do Congresso Nacional: Promulgada.\n17/03/2025 - Transfromada em norma jurídica.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"","status":"concluida","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/167530"},{"proposicao":"38/2025","tipo":"PLP","casa":"SF","ementa":"Altera o art. 6º-A da Lei Complementar nº 200, de 30 de agosto de 2023, para exigir a redução horizontal de benefícios tributários em caso de apuração de déficit primário do Governo Central.","autor":"Alessandro Vieira","relator":"","impacto":"O projeto propõe alterar a Lei que estabelece o Novo Arcabouço Fiscal para exigir a redução de benefícios tributários, financeiros e creditícios quando o Governo Central apurar um déficit primário. A proposta determina que, em caso de déficit, esses benefícios sejam reduzidos em até 10% no ano seguinte, até que se alcance um superávit primário.","tramitacao":"26/05/2025 CCJ - Recebido nesta Comissão. Matéria aguardando distribuição.","atuacao":"","percepcao":"","status":"atencao","assessor":"","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/167248"},{"proposicao":"22/2025","tipo":"PLP","casa":"SF","ementa":"Dispõe sobre prazo para liquidação de restos a pagar não processados e dá outras providências.","autor":"Senador Randolfe Rodrigues (PT/AP)","relator":"","impacto":"Após análise da legislação pertinente, do Avulso e do texto substitutivo, e por não haver repercussões negativas diretas para o Exército Brasileiro, o EME é favorável ao PLP nº 22/2025. Caso aprovado, permitirá a utilização de empenhos cancelados, abrindo espaço para outras prioridades no orçamento de 2025 e garantindo maior previsibilidade e estabilidade orçamentária para o planejamento das missões da Força Terrestre. O EME propõe a exclusão do prazo de liquidação para os restos a pagar não processados de materiais de emprego militar, garantindo previsibilidade orçamentária e flexibilidade nas aquisições internacionais, fundamentais para a Defesa da Pátria diante do cenário geopolítico atual.","tramitacao":"19/02 Mesa SF: aprovado substitutivo.\n25/02 Mesa CD: designado relator o Dep Danilo Forte.\n11/03: Plenário CD: incluído na pauta.\n18/03: Plenário CD: aprovado o substitutivo. A matéria retorna ao Senado.\n19/03: Plenário SF: aprovado o Substitutivo da Câmara dos Deputados. A matéria vai à sanção.\n21/03: Sancionada integralmente: LC 215, de 21 MAR 25","atuacao":"Acompanhar","percepcao":"Proposição de emenda pelo EME, com as justificativas:\n- \"§ 4º - Não haverá prazo de liquidação para os restos a pagar não processados dos materiais de emprego militar das Forças Armadas e essenciais para a Defesa da Pátria.\"\nTal emenda visa fazer frente ao atual cenário geopolítico que promove o reaparelhamento das Forças Armadas no mundo e amplia substancialmente as demandas por produtos de Defesa, bem com restringe o cumprimento dos prazos definidos em lei. Em consequência, a extensão dos prazos de entrega dos materiais de emprego militar (MEM), em especial dos itens importados, flexibiliza a negociação com os fornecedores internacionais, viabilizando a manutenção dos estoques estratégicos logísticos, referente aos componentes essenciais para o emprego das Forças Armadas em prol da sua missão precípua de Defesa da Pátria.\n- Designado assessor: Cap TATIANA","status":"interesse","assessor":"Cap TATIANA","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/167182"},{"proposicao":"1/092025","tipo":"PLP","casa":"CD","ementa":"Institui o Imposto Sobre a Propriedade de Arma de Fogo - IPAF, de competência da União, e dá outras providências.","autor":"Alencar Santana - PT/SP, Rubens Pereira Júnior - PT/MA, Ana Paula Lima - PT/SC e outros","relator":"","impacto":"","tramitacao":"3/02/25 Mesa Diretora CD: Apresentação.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"- Designado assessor: Ten Cel ANDRIES","status":"interesse","assessor":"Ten Cel ANDRIES","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2482491"},{"proposicao":"444/2025","tipo":"PL","casa":"CD","ementa":"Altera a Lei nº 12.351, de 22 de dezembro de 2010, que dispõe sobre a exploração e produção de petróleo sob o regime de partilha de produção, para destinar percentual dos royalties às Forças Armadas e às Forças de Segurança Pública.","autor":"Dep Silvia Waiãpi - PL/AP","relator":"","impacto":"","tramitacao":"13/02/25 Mesa Diretora CD: Apresentação.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"- Designado assessor: Ten Cel CURVO","status":"interesse","assessor":"Ten Cel CURVO","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2483942"},{"proposicao":"48/2024","tipo":"VET","casa":"CN","ementa":"Veto parcial aposto ao PLP 210 de 2024 (Autorização para contingenciamento e bloqueio de emendas parlamentares não impositivas).","autor":"PR","relator":"","impacto":"O Art. 3º do PLP autoriza o bloqueio de até 15% das emendas parlamentares não impositivas para cumprir normas fiscais, sem contar para os limites da LC nº 200/2023 e sem aumentar despesas discricionárias. O veto argumenta que o artigo não inclui emendas impositivas, o que contrariaria o STF e violaria princípios constitucionais. O EME é favorável à manutenção do veto, pois depreende que garante uma maior base do orçamento sujeita ao contingenciamento ou o bloqueio e, caso não fosse vetado, poderia alcançar repercussões negativas para o orçamento discricionário no Exército Brasileiro.","tramitacao":"17/06 Mesa Diretora CN: Retirado da pauta da Sessão Conjunta por acordo de líderes.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"- No contexto do impasse das emendas parlamentares, este veto tende a ser derrubado pelo Parlamento, que busca evitar a retomada do poder sobre o orçamento pelo Executivo.\n- Designado assessor: Maj Pires","status":"atencao","assessor":"Maj Pires","link":"https://www.congressonacional.leg.br/materias/vetos/-/veto/detalhe/17009"},{"proposicao":"47/2024","tipo":"VET","casa":"CN","ementa":"Veto Parcial aposto ao o Projeto de Lei do Congresso Nacional nº 3, de 2024 (PLDO 2025), que \"Dispõe sobre as diretrizes para a elaboração e a execução da Lei Orçamentária de 2025 e dá outras providências.\"","autor":"PR","relator":"","impacto":"Foi sancionada a LDO 2025 (Lei nº 15.080, de 30 DEZ 2024), com vetos parciais. Em uma análise preliminar do texto sancionado, observou-se que foram vetados alguns dispositivos referentes à vedação da possibilidade do bloqueio de emendas impositivas. No Anexo III, foi vetada integralmente a Seção III, que trata \"Das demais despesas ressalvadas\", incluindo a implantação do Sistema Integrado de Monitoramento de Fronteiras-SISFRON. Assim como na LDO 2024, foi vetado integralmente o Anexo VIII - Prioridades e Metas, incluindo, no Programa 6112 - Defesa Nacional, a modernização de 1 (um) Sistema de Artilharia Antiaérea, dentro do Prg EE DAAe.","tramitacao":"17/06 Mesa Diretora CN: resultado da Sessão Conjunta:\n- Dispositivos nº 3 e 4, referente ao emprego de recursos em rodovias estaduais, municipais e hidrovias: VETOS DERRUBADOS.\n- Dispositivo nº 17, referente ao bloqueio de RP de 2019 a 2022: NÃO APRECIADO.\n- Dispositivos nº 45 e 46, referentes ao cancelamento de RPNP por desistência do credor: VETOS DERRUBADOS.\n- Dispositivo nº 54, referente à inclusão do SISFRON como despesa ressalvada: NÃO APRECIADO.\n- Dispositivo nº 162, referente à meta de modernização de 1 sistema de DAAe: NÃO APRECIADO.\n26/02/2026 - Declarado prejuticado por não ter sido votado até o término no exercício financeiro da LOA 2025.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"- Seguindo a tendência da LDO 2024 e considerando que não geram impactos significativos que façam valer a pena a derrubada pelo Legislativo, os trechos vetados que afetam diretamente a Força tendem a ser mantidos.\n- Designado assessor: Maj Pires","status":"concluida","assessor":"Maj Pires","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/166964"},{"proposicao":"4920/2024","tipo":"PL","casa":"CD","ementa":"Altera a Lei nº 3.765, de 4 de maio de 1960, e estabelece idade mínima de transferência dos militares à reserva remunerada, a pedido.","autor":"Poder Executivo","relator":"","impacto":"O projeto de lei traz implicações significativas para os militares, com destaque para a imposição da idade mínima de 55 anos para a reserva remunerada. Essa exigência ignora as especificidades do serviço militar, que, conforme estudos das Forças Armadas, é muito mais gravoso que o trabalho civil, com jornadas que, em 30 anos, equivalem a cerca de 45 anos de serviço civil devido a horas extras não remuneradas e condições insalubres. Essa alteração afronta o princípio da dignidade humana, pois os militares não recebem compensações típicas de aposentadorias especiais, como adicionais noturnos, de insalubridade e periculosidade. Além disso, a regra de transição é insuficiente e pode ser considerada inconstitucional por violar a isonomia e a segurança jurídica, ao impor regimes distintos sem critérios equitativos. O projeto também fragiliza a proteção social ao extinguir pensões por \"morte ficta\" e para beneficiários de 2ª e 3ª ordens, desamparando familiares vulneráveis. A exclusão de pensões para militares punidos, mesmo com mais de 10 anos de serviço, afeta famílias que já contribuíram significativamente. A iminência dessas mudanças já provoca pedidos de transferência para a inatividade, elevando o risco de evasão em massa de militares qualificados e agravando o déficit de efetivo. A manutenção de critérios baseados no tempo de efetivo serviço militar e regras de transição mais amplas e justas são essenciais para preservar a dignidade, o equilíbrio da carreira e a proteção das famílias dos militares.","tramitacao":"17/12 Mesa Diretora CD: Apresentação.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"A Bancada da Bala se mobilizou rapidamente para retirar o Projeto da pauta do Plenário da CD, evitando que fosse votado na semana em que foi apresentado, empurrando sua tramitação para 2025 com o objetivo de que tramite pelas Comissões Temáticas da Casa.\n- Designado assessor: TC Curvo","status":"interesse","assessor":"TC Curvo","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2480445"},{"proposicao":"4841/2024","tipo":"PL","casa":"CD","ementa":"Altera as Leis nº 6.880, de 9 de dezembro de 1980 (Estatuto dos Militares), 3.765, de 4 de maio de 1960, e 13.954, de 16 de dezembro de 2019, para dispor sobre os proventos dos militares inativos, as pensões militares e a transferência para a reserva remunerada.","autor":"Pedro Campos - PSB/PE\nTabata Amaral - PSB/SP\nRafael Brito - MDB/AL\nFelipe Carreras - PSB/PE\nDuda Salabert - PDT/MG\nLuciano Ducci - PSB/PR\nRenan Ferreirinha - PSD/RJ","relator":"","impacto":"Propõe as seguintes alterações no regime previdenciário dos militares: 1. Majoração da contribuição padrão para 14%; 2. Idade mínima para entrada na reserva de 55 anos para oficiais e\n53 anos para praça; 3. Fim da integralidade e paridade de aposentadorias; 4. Fim da integralidade e paridade das pensões; 5. Regramento similar aos demais regimes em relação à duração\ndas pensões, com pensão vitalícia para cônjuge ou companheiro apenas para aqueles com mais de 45 anos.","tramitacao":"11/12 Mesa Diretora CD: Apresentação.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"O Dep Pedro Campos afirmou em suas redes sociais que vai solicitar o arquivamento do projeto pelo fato de atincir tambném as policias militares e civis. Será reescrito e apresentado novamente, atingindo apenas os militares das Forças Armadas.\n- Designado assessor: TC Curvo","status":"concluida","assessor":"TC Curvo","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2479306"},{"proposicao":"121/2024","tipo":"PLP","casa":"SF","ementa":"Institui o Programa de Pleno Pagamento de Dívidas dos Estados (Propag), destinado a promover a revisão dos termos das dívidas dos Estados e do Distrito Federal com a União firmadas no âmbito da Lei nº 9.496, de 11 de setembro de 1997, e das Leis Complementares nºs 159, de 19 de maio de 2017, 178, de 13 de janeiro de 2021, e 201, de 24 de outubro de 2023 e prevê instituição de fundo de equalização federativa.","autor":"Senador Rodrigo Pacheco (PSD/MG)","relator":"","impacto":"O artigo 32-A, introduzido pelo PLP 121/2024 (inserido no texto aprovado na Câmara), altera a Lei nº 4.320, de 1964, tornando permanente a autorização para a execução provisória de despesas essenciais caso a LOA não seja publicada antes do início do exercício financeiro. Essa autorização, anteriormente prevista anualmente na LDO, permite atender a obrigações constitucionais ou legais, serviço da dívida e outras despesas da LDO, com os gastos sendo tratados como antecipação de crédito ajustável após a aprovação da LOA. Há restrições para criação de cargos ou alterações estruturais de carreiras, e até a publicação do cronograma mensal da LRF, os pagamentos realizados serão considerados antecipações, assegurando o funcionamento básico do governo.\n17/12 - Proposta de artigo 32-A, que iria alterar a Lei nº 4.320/64, SUPRIMIDA no texto final aprovado no Plenário do SF.","tramitacao":"14/08 PLEN SF: APROVADO O SUBSTITUTIVO. Enviado à CD.\n14/08 PLEN CD: Aprovada a Redação Final assinada pelo relator, Dep. Doutor Luizinho (PP-RJ). A Matéria retorna ao Senado (PLP 121-A/2024).\n11/12 PLEN SF: RQS 902, Sen Carlos Portinho (PL/RJ), em nome da Liderança do PL, requer destaque, para\nvotação em separado, do art. 17 do PLP 121/2024 (Substitutivo-CD), que propõe a inclusão do artigo 32-A na Lei nº 4.320, de 1964, tornando permanente a autorização para a execução provisória de despesas essenciais caso a LOA não seja publicada antes do início do exercício financeiro.\n17/12 - Plenário do SF: APROVADA (proposta de artigo 32-A, que iria alterar a Lei nº 4.320/64, SUPRIMIDA).\n20/12 - SF-SEXPE: A matéria vai à sanção.\n13/01/2025 - Transformado em norma jurídica (Lei Complementar 212/2025).","atuacao":"Acompanhar","percepcao":"- O artigo 32-A foi inserido no texto final aprovado na CD, em 10/12 - Proposta de artigo 32-A, após acordo de lideranças, pela para autorizar a execução provisória do PLOA 2025, caso a LDO 2025 não fosse aprovada ainda em 2024 (não constava no texto inicial aprovado no Senado). A matéria retorna ao Senado após sofrer modificações na Câmara.\n- Em 17/12, no mesmo dia que foi aprovado na CMO o relatório final do PLDO 2025, foi aprovado no Plenaário do SF o o texto final da proposição, SUPRIMINDO a proposta de artigo 32-A, que iria alterar a Lei nº 4.320/64.\n- Designado assessor: Maj Pires","status":"concluida","assessor":"Maj Pires","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2454400&fichaAmigavel=nao"},{"proposicao":"213/2024","tipo":"PLP","casa":"CD","ementa":"Institui normas para a elaboração e a execução orçamentária, alinhadas às metas fiscais e compatíveis com a plena realização da programação de trabalho dos orçamentos fiscal e da seguridade social.","autor":"Senador Marcos do Val (PODEMOS/ES)","relator":"","impacto":"A proposta impacta o Exército ao aprimorar o planejamento e execução orçamentária, favorecendo projetos estratégicos com maior previsibilidade e proteção contra contingenciamentos arbitrários. No entanto, a exigência de detalhamento e limites para projetos pode restringir iniciativas menores ou regionais. Ao priorizar a sustentabilidade da dívida pública, ajustes fiscais mais rigorosos podem afetar o orçamento da Defesa, exigindo atenção para que iniciativas essenciais sejam contempladas e preservadas no novo modelo.","tramitacao":"10/12 CCJC: Matéria aguardando distribuição.","atuacao":"Acompanhar","percepcao":"- Designado assessor: TC Alessandra","status":"interesse","assessor":"TC Alessandra","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2473389"},{"proposicao":"47/2024","tipo":"PEC","casa":"SF","ementa":"Altera o Art. 7º que define os direitos dos trabalhadores e o Art. 37 da Constituição Federal para definir que o teto remuneratório incide sobre as remunerações, subsídios, proventos, pensões, outras espécies remuneratórias e verbas de natureza indenizatória.","autor":"Senador Cleitinho (REPUBLICANOS/MG)","relator":"","impacto":"A proposta, se aprovada, pode dificultar a gestão financeira e operacional do Exército ao limitar o reconhecimento de despesas específicas como indenizatórias. Isso pode desincentivar deslocamentos estratégicos, missões em áreas de difícil acesso e a permanência de militares qualificados na ativa. O impacto será particularmente severo em situações que dependem de indenizações para viabilizar operações e transferências.","tramitacao":"10/12 CCJC: Matéria aguardando distribuição.","atuacao":"Acompanhar","percepcao":"Proposta com teor semelhante ao da PEC 45/2024. Diferença entre as duas propostas: a PEC 45/2024 permite exceções para parcelas indenizatórias expressamente previstas em lei complementar, enquanto a PEC 47/2024 inclui todas as parcelas indenizatórias no cálculo do teto, sem exceções. Além disso, a PEC 47/2024 impõe o teto à soma de aposentadorias, pensões e remunerações acumuladas, enquanto a PEC 45/2024 não aborda diretamente esses casos. Isso torna a PEC 47/2024 mais restritiva, com impacto maior sobre militares, pois limita benefícios como diárias e auxílios, que passam a integrar o cálculo do teto.\n- Designado assessor: TC Alessandra","status":"interesse","assessor":"TC Alessandra","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/166348"},{"proposicao":"45/2024","tipo":"PEC","casa":"SF","ementa":"Altera os art. 37, art. 163, art. 203, art. 212-A e art. 239 da Constituição e o art. 76 do Ato das Disposições Constitucionais Transitórias - ADCT e acresce os art. 138 e art. 139 ao ADCT.","autor":"Poder Executivo","relator":"","impacto":"A PEC pode trazer restrições financeiras e burocráticas que impactam diretamente a flexibilidade operacional e administrativa do Exército. Em especial, a exigência de lei complementar para parcelas indenizatórias e a possibilidade de redução de indenizações pelo Executivo podem desincentivar missões e transferências, prejudicando a eficiência e a mobilidade estratégica. Além disso, a desvinculação de receitas e os limites para o crescimento de despesas vinculadas podem reduzir a capacidade de investimento e manutenção das Forças Armadas.","tramitacao":"03/12 CCJC: recebimento. \n19/12: Plenário CD: aprovada. Segue para o SF.\n20/12: Plenário CD: aprovada como PEC 54/2024 e promulgada a EC 135/2024.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"Proposta com teor semelhante ao da PEC 47/2024. Diferença entre as duas propostas: a PEC 45/2024 permite exceções para parcelas indenizatórias expressamente previstas em lei complementar, enquanto a PEC 47/2024 inclui todas as parcelas indenizatórias no cálculo do teto, sem exceções. Além disso, a PEC 47/2024 impõe o teto à soma de aposentadorias, pensões e remunerações acumuladas, enquanto a PEC 45/2024 não aborda diretamente esses casos. Isso torna a PEC 47/2024 mais restritiva, com impacto maior sobre militares, pois limita benefícios como diárias e auxílios, que passam a integrar o cálculo do teto.\n- Designado assessor: Cap Tatiana","status":"interesse","assessor":"Cap Tatiana","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2474283"},{"proposicao":"210/2024","tipo":"PLP","casa":"CD","ementa":"Altera a Lei Complementar nº 200, de 30 de agosto de 2023, que institui regime fiscal sustentável para garantir a estabilidade macroeconômica do País e criar as condições adequadas ao crescimento socioeconômico, e dá outras providências.","autor":"Dep José Guimarães (PT/CE)","relator":"","impacto":"- A proposta inicial enviada pelo ao Congresso autorizava o governo a contingenciar e bloquear emendas parlamentares até 15% das dotações, aplicando o mesmo tratamento das despesas discricionárias. A versão final aprovada pela Câmara, no entanto, limita o bloqueio às emendas não obrigatórias, trecho que foi vetado pelo Presidente Lula. O veto foi baseado em uma argumentação de que o bloqueio e contingenciamento das emendas impositivas violariam a decisão do STF que determinou que qualquer regra aplicada às despesas discricionárias do Executivo também se aplica às emendas parlamentares.\n- A nova legislação prevê, também, que, entre 2025 e 2030, superávits financeiros de fundos públicos (incluindo o Fundo do Exército) poderão ser utilizados para amortizar a dívida pública.","tramitacao":"29/11 - Mesa Diretora CD: apresentado.\n17/12 - MESA CD: Apresentação do PRLE n. 1 PLEN (Parecer Preliminar às Emendas de Plenário), pelo Deputado Átila Lira (PP/PI).\n30/12 - Transformado na Lei Complementar 211/2024. Vetado parcialmente.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"- A proposta inicial enviada pelo ao Congresso autorizava o governo a contingenciar e bloquear emendas parlamentares até 15% das dotações, aplicando o mesmo tratamento das despesas discricionárias. A versão final aprovada pela Câmara, no entanto, limita o bloqueio às emendas não obrigatórias, trecho que foi vetado pelo Presidente Lula. O veto foi baseado em uma argumentação de que o bloqueio e contingenciamento das emendas impositivas violariam a decisão do STF que determinou que qualquer regra aplicada às despesas discricionárias do Executivo também se aplica às emendas parlamentares.\n- A nova legislação prevê, também, que, entre 2025 e 2030, superávits financeiros de fundos públicos (incluindo o Fundo do Exército) poderão ser utilizados para amortizar a dívida pública.\n- Designado assessor: Cap Tatiana","status":"concluida","assessor":"Cap Tatiana","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2473389"},{"proposicao":"4413/2024","tipo":"PL","casa":"CD","ementa":"Identifica a fim de consolidar o cumprimento do teto remuneratório no setor público e dá outras providências.","autor":"Dep Guilherme Boulos (PSOL/SP)","relator":"","impacto":"","tramitacao":"18/11 Mesa Diretora CD: Apresentação.\n22/11 - MESA CD: Apresentação do REQ n. 4586/2024 (Requerimento de Urgência (Art. 155 do RICD)), pelo Deputado Guilherme Boulos (PSOL/SP -Fdr PSOL-REDE) e outros, que \"Requer regime de urgência para apreciação do PL nº 4413/2024. \".\n13/03/2025 - Apensado ao PL 4077/2024.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"- Designado assessor: Cel Sidney Viana","status":"interesse","assessor":"Cel Sidney Viana","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2469722"},{"proposicao":"43/2024","tipo":"PEC","casa":"SF","ementa":"Altera o art. 166 da Constituição, para dispor sobre critérios de aprovação e execução das emendas às leis de natureza orçamentária.","autor":"Sen Alessandro Vieria (MDB/SE)","relator":"","impacto":"- A proposta de extinção das Emendas de Comissão (RP8) da forma apresentada na proposição pode ter impactos negativos significativos para o Exército, pois os recursos serão transferidos para Emendas Individuais (RP6) e de Bancada (RP7). Atualmente, os recursos das Emendas de Comissão (RP8) são provenientes de cortes lineares no orçamento das pastas do Executivo, realizados pelo Legislativo durante a tramitação da peça orçamentária no Congresso Nacional. Esses valores funcionam como uma forma de recomposição para a Força dos realizados pelo Legislativo, principalmente por meio da destinação de emendas ao PLOA pelas Comissões Temáticas de Defesa Nacional das duas Casas, frequentemente destinando recursos para os Projetos Estratégicos do Exército.\n- O parecer do EME sobre a PEC nº 43/2024 destaca que, embora a proposta busque coibir abusos na execução de emendas orçamentárias, a extinção das emendas de comissão pode trazer impactos severos para o Exército. Essas emendas são essenciais para financiar programas estratégicos e iniciativas críticas, garantindo a segurança e modernização da Força. A redistribuição dos recursos para emendas individuais e de bancada poderá resultar em concentração desigual de fundos e comprometer o planejamento previsto para 2024-2027. O EME propõe a manutenção das emendas de comissão, com maior transparência e detalhamento de suas finalidades, como alternativa para preservar o financiamento do setor de defesa. Caso essa proposta não seja aceita, o parecer do ODG é desfavorável à PEC.","tramitacao":"13/11 Plenário do SF: a proposta vai à publicação.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"- A proposta de extinção das Emendas de Comissão (RP8), conforme apresentada, pode gerar impactos negativos significativos para o Exército. Isso ocorre porque os recursos seriam redirecionados para as Emendas Individuais (RP6) e de Bancada (RP7). Atualmente, as Emendas de Comissão (RP8) são financiadas por cortes lineares no orçamento das pastas do Executivo, realizados pelo Legislativo durante a tramitação do orçamento no Congresso Nacional. Esses recursos, quando recebidos, atuam como uma forma de recomposição orçamentária para a Força, especialmente por meio das Comissões Temáticas de Defesa Nacional das duas Casas, que frequentemente destinam verbas por meio de emendas aos Projetos Estratégicos do Exército.\n- Existe um movimento na Câmara dos Deputados para apresentar uma PEC com o mesmo teor, liderado pelo Dep Altineu Côrtes (PL/RJ), em ratalização aos movimentos realizados pelo Executivo, via Ministro Flávio Dino. no contexto do impasse das emendas, que se arrasta desde agosto de 2024.\n- Designado assessor: TC Alessandra","status":"normal","assessor":"TC Alessandra","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/166127"},{"proposicao":"4336/2024","tipo":"PL","casa":"CD","ementa":"Revoga o art. 20 da Lei nº 3.765, de 4 de maio de 1960, que dispõe sobre as pensões militares, para extinguir a pensão militar nos casos de perda do posto e da patente por oficiais ou da expulsão da praça ou do seu não relacionamento como reservista por efeito de sentença ou em decorrência de ato da autoridade competente.","autor":"Dep Albuquerque (REPUBLICANOS/RR)","relator":"","impacto":"","tramitacao":"12/11 Mesa Diretora CD: Apresentação.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"- Designado assessor: Cel Sidney Viana","status":"normal","assessor":"Cel Sidney Viana","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2468512"},{"proposicao":"4077/2024","tipo":"PL","casa":"CD","ementa":"Dispõe sobre o teto remuneratório estabelecido no inciso XI do caput e no § 9º do art. 37 da Constituição Federal e o limite para o pagamento das parcelas de caráter indenizatório previstas no § 11 do art. 37 da Constituição Federal.","autor":"Dep Chico Alencar (PSOL/RJ)","relator":"","impacto":"A aprovação do projeto de lei que limita as parcelas indenizatórias a 10% além do teto remuneratório impactaria todos os militares ao restringir seus ganhos, independentemente da patente ou função. Isso desincentivaria transferências e missões em áreas remotas ou de alto custo de vida, dificultando a mobilidade e a flexibilidade operacional das Forças Armadas. Além disso, ao impor limites financeiros em compensações de transferências e diárias, o projeto pode afetar a atratividade de diversas posições, gerando insatisfação e prejudicando a motivação para assumir funções que exigem deslocamentos frequentes.","tramitacao":"24/10 Mesa Diretora CD: Apresentação.\n18/11 Mesa Diretora CD: Às Comissões de Administração e Serviço Público; Finanças e Tributação (Mérito e Art. 54, RICD) e Constituição e Justiça e de Cidadania (Art. 54 RICD) Proposição Sujeita à Apreciação Conclusiva pelas Comissões - Art. 24 II Regime de Tramitação: Ordinário (Art. 151, III, RICD)\n25/11 - COORDENAÇÃO DE COMISSÕES PERMANENTES: Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 26/11/2024.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"- Designado assessor: Cel Sidney Viana","status":"normal","assessor":"Cel Sidney Viana","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2464225&fichaAmigavel=nao"},{"proposicao":"178/2024","tipo":"PLP","casa":"CD","ementa":"Dispõe sobre a implementação de normas de transparência e rastreabilidade, que viabilizem o controle social sobre os gastos públicos.","autor":"Dep Zé Vitor (PL/DF)","relator":"","impacto":"O Projeto de Lei Complementar propõe aprimorar a transparência e rastreabilidade na execução das emendas parlamentares, fortalecendo o controle social e a segurança jurídica no uso dos recursos públicos. Almeja-se criar normas alinhadas aos princípios constitucionais e atender às questões levantadas pelo STF sobre a necessidade de critérios claros para a execução dessas emendas. Entre as medidas, destaca-se a priorização de obras inacabadas e ações estruturantes, além de fortalecer o papel do TCU na fiscalização dos recursos e integrar as emendas a sistemas governamentais como o Transferegov.br. O projeto visa assegurar o uso responsável e eficiente das verbas, especialmente em áreas prioritárias como saúde e educação, promovendo um marco regulatório mais robusto e aderente ao interesse público.","tramitacao":"31/10 - Mesa Diretora CD: apresentado.\n20/02/2025 - CASP: Recebimento pela CASP, com a proposição PLP-1/2025 apensada.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"Mais uma proposta que propões a implementação de novas normas para a indicação e execução das emendas parlamentares. O projeto é o do Dep Zé Vitor (PL/MG), com medidas para melhorar a transparência e a rastreabilidade sas emendas, mas sem limite às indicações dos congressistas no Orçamento e sem poder para o governo mexer nas despesas por conta própria. A proposta foi classificado nos bastidores como um texto mais alinhado aos interesses do “baixo clero” (como são conhecidos os parlamentares com menos visibilidade) e da base dos parlamentares do Centrão.","status":"normal","assessor":"","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2466475"},{"proposicao":"175/2024","tipo":"PLP","casa":"CD","ementa":"Dispõe sobre a proposição e execução de emendas parlamentares na lei orçamentária anual e dá outras providências.","autor":"Dep Rubens Pereira Junior (PT/MA)","relator":"","impacto":"O projeto limita a destinação de recursos de Emendas Coletivas (de Bancada e Comissão) para projetos e ações estruturantes destinados a um rol taxativo de políticas públicas que não inclui a Defesa Nacional, apenas abre a possibilidade de incluí-la no PLDO, anualmente. Além disso, obriga os órgãos executores de políticas públicas a publicar portarias, anualmente, com critérios para priorização da execução dos projetos e ações estruturantes, o que pode limitar mais ainda o recebimento destes recursos pelo Exército. No que se refere às Emendas de Bancada, outro ponto prejudicial é que a proposta diminui consideravelmente o Nr limite de emendas que cada bancada estadual pode destinar. Por fim, outra inovação desfavorável à Força é a obrigatoriedade da destinação mínima de 50% das Emendas de Comissão para ações e serviços públicos de saúde.","tramitacao":"05/11 - Plenário CD: Aprovada a Redação Final assinada pelo relator, Dep. Elmar Nascimento (União-BA).\n13/11 - Mesa Diretora SF: aprovado no Senado o texto-base do PLP 175/2024. \n18/11 - Plenário SF: Concluída a votação dos 4 destaques: Suprimidos trechos relacionados a possibilidade de bloqueio de dotações de emendas parlamentares; Removida a obrigatoriedade de destinar 50% das emendas de comissão à saúde pública. Mantido dispositivo que estabelece que as lideranças partidárias indicarão as emendas de comissões; Mantida regras sobre limites de crescimento de despesas para emendas parlamentares. Aprovada a subemenda ao Substitutivo do Relator, nos termos do acordo de Plenário. A matéria retorna à CD.\n19/11 - Plenário CD: Aprovada nova Redação Final. Foi reestabelecida a obrigatoriedade de destinar 50% das emendas de comissão à saúde pública e o limite máximo de 8 emendas por Bancada Estadual, mais 3 emendas que se destinem à continuidade de obras já iniciadas, até sua conclusão. A matéria vai à Sanção.\n21/11 - Mesa Diretora CD: Apresentação do Autógrafo. Remetido à sanção.\n26/11 - Mesa Diretora CD: Transformado na Lei Complementar 210/2024.","atuacao":"- Durante a atuação junto à assessoria do Sen Angelo Coronel para incluir a Defesa Nacional no rol taxativo de políticas públicas estruturantes no PLP 172/2024, a A4 descobriu que poderia ser apresentado um novo projeto mais restritivo e prejudicial à Força.\n - Assim, atuou-se junto ao Diretor da Consultoria-Geral da CD e a informação foi confirmada, sendo corroborada na apresentação do PLP 175/2024, com a Defesa Nacional excluída do rol taxativo de políticas públicas estruturantes. \n - Após isso, o Ch/A4 informou o Cmt Ex sobre a questão, e o Dep Rubens Pereira Júnior (PT/MA), autor da proposição, foi contactado, informando que vai incluir a Defesa Nacional no rol em questão.\n - A matéria foi enviada ao EME para análise e a tramitação será acompanhada na CD e no SF, com atenção na alteração do texto solicitada ao autor.","percepcao":"A proposta de lei complementar busca implementar o acordo firmado entre os Poderes em 2024, após decisões do STF, que visou corrigir distorções no uso do orçamento público e garantir uma aplicação mais justa e transparente dos recursos. O acordo determinou que as emendas parlamentares precisam seguir critérios claros para evitar privilégios e garantir que os recursos públicos sejam utilizados de forma eficiente. O Projeto busca regulamentar as emendas parlamentares ao orçamento anual, com foco em transparência, rastreabilidade e fortalecimento do papel do Legislativo, seguindo a Constituição. A proposta prioriza o repasse de recursos para municípios, especialmente os menores, promovendo maior equidade e fortalecendo as políticas públicas locais. O projeto exige a disponibilização pública dos dados de alocação e execução no Portal da Transparência, além de assegurar o monitoramento e controle das transferências, com prioridade para obras inacabadas e exigência de planos detalhados para as transferências específicas. Há ainda limites para emendas de bancada estadual e critérios rigorosos para a execução de recursos, com exigências para relatórios regulares de monitoramento e compatibilidade das emendas com o regime fiscal. A medida visa aumentar a eficiência e a responsabilidade na gestão dos recursos públicos, promovendo alinhamento com planos governamentais e focando nas necessidades da sociedade, em especial dos municípios.\n- Designado assessor: Cap Tatiana","status":"normal","assessor":"Cap Tatiana","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2466104"},{"proposicao":"172/2024","tipo":"PLP","casa":"SF","ementa":"Dispõe sobre as emendas parlamentares ao projeto de lei orçamentária anual, conforme os arts. 165, 166 e 166-A da Constituição Federal.","autor":"Senador Angelo Coronel (PSD/BA)","relator":"","impacto":"O Projeto pode aumentar a burocracia para o EB, exigindo justificativas detalhadas e maior rastreabilidade no recebimento e uso de emendas parlamentares, o que tende a dificultar o fluxo de recursos e a necessidade de relatórios detalhados de execução. Com o foco em projetos estruturantes e a conclusão de obras inacabadas, o Exército terá de investir mais em planejamento e coordenação com o Legislativo para garantir financiamento. Essa exigência de apresentação prévia de projetos estruturantes pode aumentar a complexidade na elaboração de propostas e no relacionamento com os parlamentares. Além disso, a limitação de emendas de execução obrigatória intensifica a concorrência por verbas, restringindo o orçamento disponível para novos projetos e comprometendo iniciativas estratégicas. Esse cenário pode ser ainda mais desafiador diante de controles rigorosos que buscam evitar a alocação de recursos em projetos considerados inviáveis ou incompatíveis com as diretrizes de políticas setoriais.","tramitacao":"25/10 - Plenário SF: Aguardando despacho.\n27/11 - Plenário SF: PREJUDICADA. A matéria vai ao Arquivo.","atuacao":"- Projeto apresentado pelo Sen Angelo Coronel (PSD/BA) com o objetivo de regulamentar do acordo firmado entre os Três Poderes em 20 AGO 24, em resposta às decisões do STF que suspenderam a execução das emendas.\n- No referido acordo, foi estabelecido um consenso de que as Emendas de Bancada e de Comissão teriam que ser destinadas para “Projetos Estruturantes”, o que gerou dúvidas se os projetos da Força se enquadrariam nesse termo. Desse modo, foi realizado contato com um consultor especialista em orçamento, que há muitos anos presta consultoria a parlamentares, partidos e comissões do CN, e atualmente assessora o Sen Angelo Coronel, para sanar a dúvida.\n- O consultor informou que no texto em construção constava um rol taxativo de políticas públicas cujos projetos e ações são considerados estruturantes e poderão receber recursos de Emendas de Bancada e de Comissão. Contudo, a área de Defesa Nacional não estava incluída na lista, e ele orientou que a Assessoria fizesse essa informação chegar ao Ministro da Def, para que este fizesse contato com o Dep Arthur Lira, Presidente da CD, para solicitar a inclusão da Def Nac no referido rol, antes que o texto fosse protocolado no SF.\n- Assim, o Ch A4 fez contato com o Ch ARI/MD e a informação chegou ao Presidente Lira, que concordou com a inclusão. Então, o Ministro solicitou que a A4 fizesse contato com a Assessoria do Sen para informar a aquiescência do Presidente Lira ao pedido, bem como solicitar a inclusão do texto no projeto. O contato foi realizado pela A4 e a confirmação do atendimento do pleito ocorreu por ocasião da autuação do PLP 172/2024 no Plenário do SF, em 27 OUT 24.","percepcao":"A proposta de lei complementar busca implementar o acordo firmado entre os Poderes em 2024, após decisões do STF, que visou corrigir distorções no uso do orçamento público e garantir uma aplicação mais justa e transparente dos recursos. O acordo determinou que as emendas parlamentares precisam seguir critérios claros para evitar privilégios e garantir que os recursos públicos sejam utilizados de forma eficiente. O Projeto busca regulamentar as emendas parlamentares ao orçamento anual, com foco em transparência, rastreabilidade e fortalecimento do papel do Legislativo, seguindo a Constituição. A proposta prioriza o repasse de recursos para municípios, especialmente os menores, promovendo maior equidade e fortalecendo as políticas públicas locais. O projeto exige a disponibilização pública dos dados de alocação e execução no Portal da Transparência, além de assegurar o monitoramento e controle das transferências, com prioridade para obras inacabadas e exigência de planos detalhados para as transferências específicas. Há ainda limites para emendas de bancada estadual e critérios rigorosos para a execução de recursos, com exigências para relatórios regulares de monitoramento e compatibilidade das emendas com o regime fiscal. A medida visa aumentar a eficiência e a responsabilidade na gestão dos recursos públicos, promovendo alinhamento com planos governamentais e focando nas necessidades da sociedade, em especial dos municípios.","status":"normal","assessor":"","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/165925"},{"proposicao":"162/2024","tipo":"PLP","casa":"SF","ementa":"Regulamenta os parâmetros mínimos de impessoalidade e eficiência na execução orçamentária e financeira dos entes da Federação, bem como os impedimentos de ordem técnica e os critérios para execução equitativa para execução de despesas públicas, inclusive para os fins previstos no art. 165, § 9º, inc III da Constituição Federal.","autor":"Senador Eduardo Girão (NOVO/CE)","relator":"","impacto":"A proposta de lei complementar pode aumentar a burocracia para o Exército Brasileiro, exigindo justificativas rigorosas e rastreabilidade para o recebimento de emendas, dificultando o fluxo de recursos. A limitação das emendas de execução obrigatória intensifica a concorrência por verbas, o que pode prejudicar novos projetos. Além disso, a exigência de apresentação prévia de projetos estruturantes requererá mais planejamento e coordenação com o Legislativo.","tramitacao":"17/10 - Plenário SF: Autuado o Projeto, vai à publicação","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"Projeto igual ao PLP 161/2024, apresentado pela Dep Adriana Ventura (Novo/SP), na mesma data: a proposta de lei complementar busca implementar o acordo firmado entre os Poderes em 2024, após decisões do STF, que visou corrigir distorções no uso do orçamento público e garantir uma aplicação mais justa e transparente dos recursos. O acordo determinou que as emendas parlamentares precisam seguir critérios claros para evitar privilégios e garantir que o dinheiro público seja usado de forma eficiente.\nPara isso, a lei regulamenta as emendas parlamentares (individuais, de bancada e de comissão). Ela exige rastreabilidade, identificando o autor e o destino de cada emenda, garantindo transparência total. Para as emendas de bancada e de comissão, a lei define que os recursos devem priorizar projetos estruturantes e a conclusão de obras inacabadas, evitando desperdícios. Além disso, limita as emendas de execução obrigatória ao crescimento das despesas discricionárias, assegurando o equilíbrio fiscal e evitando sobrecarga no orçamento.","status":"normal","assessor":"","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/165766"},{"proposicao":"161/2024","tipo":"PLP","casa":"CD","ementa":"Regulamenta os parâmetros mínimos de impessoalidade e eficiência na execução orçamentária e financeira dos entes da Federação, bem como os impedimentos de ordem técnica e os critérios para execução equitativa para execução de despesas públicas, inclusive para os fins previstos no art. 165, § 9º, inc III da Constituição Federal.","autor":"Dep Adriana Ventura (NOVO/SP)","relator":"","impacto":"A proposta de lei complementar pode aumentar a burocracia para o Exército Brasileiro, exigindo justificativas rigorosas e rastreabilidade para o recebimento de emendas, dificultando o fluxo de recursos. A limitação das emendas de execução obrigatória intensifica a concorrência por verbas, o que pode prejudicar novos projetos. Além disso, a exigência de apresentação prévia de projetos estruturantes requererá mais planejamento e coordenação com o Legislativo.","tramitacao":"17/10 - Mesa Diretora CD: Apresentação da matéria.\n30/10 - Mesa Diretora CD: Defirido o REQ 4279/2024. - Aguardando Despacho do Presidente da CD.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"A proposta de lei complementar busca implementar o acordo firmado entre os Poderes em 2024, após decisões do STF, que visou corrigir distorções no uso do orçamento público e garantir uma aplicação mais justa e transparente dos recursos. O acordo determinou que as emendas parlamentares precisam seguir critérios claros para evitar privilégios e garantir que o dinheiro público seja usado de forma eficiente.\nPara isso, a lei regulamenta as emendas parlamentares (individuais, de bancada e de comissão). Ela exige rastreabilidade, identificando o autor e o destino de cada emenda, garantindo transparência total. Para as emendas de bancada e de comissão, a lei define que os recursos devem priorizar projetos estruturantes e a conclusão de obras inacabadas, evitando desperdícios. Além disso, limita as emendas de execução obrigatória ao crescimento das despesas discricionárias, assegurando o equilíbrio fiscal e evitando sobrecarga no orçamento.\n- Designado assessor: Cap Tatiana","status":"normal","assessor":"Cap Tatiana","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2463000"},{"proposicao":"31/2024","tipo":"PLN","casa":"CN","ementa":"Propõe a alteração da LDO 2024, para dispor sobre o contrato de gestão, a fim de viabilizar que empresas estatais atualmente classificadas como dependentes que tenham condições de alcançar a sustentabilidade econômica e financeira passem a compor o Orçamento de Investimento das Empresas Estatais, conferindo-lhes assim maior autonomia gerencial, orçamentária e financeira.","autor":"PR","relator":"","impacto":"A proposta visa permitir que empresas estatais dependentes, como a IMBEL, por exemplo, adquiram autonomia ao assinarem contratos de gestão com o governo, que definem objetivos e metas. Isso possibilitará que estatais atualmente dependentes, mas em processo de sustentabilidade, sejam integradas ao Orçamento de Investimentos das Empresas Estatais. Essa mudança busca promover a eficiência e a independência financeira das estatais.\nO EME entende que o tema possui relevância para a IMBEL. Conforme pareceres da SEF e da IMBEL, não haverá alteração das relações da UO IMBEL com o EB. Caso aprovada a proposta, permitirá flexibilidade para a gestão financeira, conferindo condições para otimizar a gestão financeira e o desenvolvimento da empresa em face da imprevisibilidade do orçamento da União. Portanto, essa situação permitirá a abertura de conta bancária, melhores aplicações financeiras, proporcionando a possibilidade da incorporação de receitas de vendas de imóveis, de financiamentos do BNDES, FINEP, conforme parecer da IMBEL.","tramitacao":"- 4/10 CMO: Recebida a matéria.\n- 26/11 CMO: foi apresentada 1 (uma) emenda ao projeto, sem impacto para a Força.\n- 10/12 CMO: incluída e retirada de pauta, pois não tinha sido designado relator.\n- 12/12 Plenário CN: incluída na pauta (sessão cancelada). Não possuía parecer na CMO.\n- 18/12 Plenário CN: incluída e retirada da pauta (não possuía parecer na CMO).\n- 07/04/2025 Mesa Diretora CN: Declaração de prejudicialidade.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"Conforme a Nota Informativa da CONORF, o projeto de lei PLN nº 31/2024 propõe facilitar a transição de estatais dependentes da União para a independência financeira por meio de contratos de gestão, substituindo o plano de sustentabilidade econômica. Isso permitiria às empresas maior autonomia, escapando de restrições como o contingenciamento e o registro obrigatório no SIAFI, ao mesmo tempo que permanecem submetidas ao teto constitucional de salários. Contudo, o projeto não detalha como serão tratadas as despesas cobertas por receitas próprias e como a flexibilização das regras se compatibilizará com a apuração do resultado primário. As principais lacunas são a falta de clareza sobre o tratamento das despesas financiadas por receitas próprias, a falta de critérios específicos para regulamentar a transição das empresas estatais e a ausência de informações sobre a compatibilidade das novas regras com leis fiscais como a LC nº 200/2023. Essas incertezas podem comprometer a execução uniforme e o cumprimento das metas fiscais previstas na Lei de Responsabilidade Fiscal (LRF).\n- Não houve acordo para aprovação da matéria, não tendo sido nem designado relator na CMO. A matéria deve ser arquivada.\n- Designado assessor: Maj Pires","status":"normal","assessor":"Maj Pires","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/165624"},{"proposicao":"66/2023","tipo":"PEC","casa":"CD","ementa":"Institui limite para o pagamento de precatórios pelos Municípios, abre novo prazo de parcelamento especial de débitos dos Municípios com seus regimes próprios de previdência social e com o Regime Geral de Previdência Social e dá outras providências.","autor":"Senado Federal - Jader Barbalho - MDB/PA","relator":"Dep. Darci de Matos","impacto":"O Art 4º do Substitutivo aprovado no Senado e enviado para a Câmara estabelece que, entre 2025 e 2030, até 25% do superávit financeiro das fontes de recursos vinculados dos fundos públicos do Poder Executivo da União poderá ser usado para financiar projetos voltados à mudança climática e à transformação ecológica. A partir de 2031, os recursos deverão ser devolvidos aos fundos de origem, de forma gradual, conforme o retorno dos financiamentos. O Ministério da Fazenda será responsável por definir as regras para a aplicação dessa medida.\nO EB possui o Fundo do Exército, voltado para o financiamento de projetos estratégicos, modernização de equipamentos e outras necessidades específicas da Força. Esse fundo recebe recursos de fontes como doações, transferências do governo, esforço próprio de arrecadação e rendimentos de investimentos. Com a aprovação da referida PEC, até 25% do superávit desse fundo poderá ser usado entre 2025 e 2030 para financiar projetos ambientais. A devolução começará em 2031, o que pode impactar o planejamento de longo prazo da utilização dos recursos. A regulamentação detalhada trará mais clareza, mas há incertezas sobre o impacto total.","tramitacao":"14/08/24 Plenário do SF: Aprovado o Substitutivo apresentado pelo relator, Sen Carlos Portinho. A matéria vai à Câmara dos Deputados.\n22/08/2024 Mesa Diretora da CD: Recebido do Senado Federal o autógrafo do texto aprovado.\n16/10/2024 Mesa Diretora da CD: À CCJC. Proposição Sujeita à Apreciação do Plenário. Regime de Tramitação: Especial.\n18/10/2024 CCJC: Designado Relator, Dep Darci de Matos (PSD-SC).\n24/10/2024 CCJC: Parecer do Relator, Dep. Darci de Matos (PSD-SC), pela admissibilidade, com emenda supressiva. \n29/10/2024 CCJC: Aprovado o parecer.","atuacao":"Acompanhar.","percepcao":"14/08/2024 - O Min da Fazenda apresentou ao Relator no SF, Sen Calos Portinho, a proposta de incluir no texto a desvinculação de fundos do Poder Executivo da União para financiamento de projetos relacionados ao enfrentamento, à mitigação e adaptação à mudança do clima, que foi incluída no Susbtitutivo aprovado. O Art 4º do referido Substitutivo estabelece que, entre 2025 e 2030, até 25% do superávit financeiro das fontes de recursos vinculados dos fundos públicos do Poder Executivo da União poderá ser usado para financiar projetos voltados à mudança climática e à transformação ecológica. A partir de 2031, os recursos deverão ser devolvidos aos fundos de origem, de forma gradual, conforme o retorno dos financiamentos. O Ministério da Fazenda será responsável por definir as regras para a aplicação dessa medida.","status":"normal","assessor":"","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2454495&fichaAmigavel=nao"},{"proposicao":"35/2024","tipo":"PEC","casa":"SF","ementa":"Altera a Constituição Federal para incluir o Plano Pluriquadrienal como norteador das despesas e investimentos previstos no orçamento da União.","autor":"Sen Hamilton Mourão (Rep/RS)","relator":"","impacto":"A inclusão do Plano Pluriquadrienal (PPQ) na Constituição pode impactar o Exército de forma significativa. O planejamento de longo prazo permitirá melhor coordenação e previsibilidade em relação a investimentos em infraestrutura, tecnologia e defesa. O PPQ poderá facilitar o desenvolvimento de projetos estratégicos, como a modernização de equipamentos e o fortalecimento da capacidade operacional. Além disso, ao integrar o conceito de desenvolvimento sustentável, poderá direcionar investimentos para áreas como energias renováveis e inovação tecnológica, alinhando o Exército com as metas nacionais de sustentabilidade e eficiência.","tramitacao":"25/09 Plenário do SF: A proposta vai à publicação.\n09/10 CCJ: AGUARDANDO DESIGNAÇÃO DO RELATOR.","atuacao":"Acompanhar.","percepcao":"A PEC 35/2024 propõe a inclusão do Plano Pluriquadrienal (PPQ) na Constituição Federal como instrumento de planejamento estratégico de longo prazo, com duração de 20 anos, para nortear as despesas e investimentos públicos, complementando o PPA, LDO e LOA. O PPQ visa integrar o conceito de desenvolvimento sustentável ao planejamento governamental, preenchendo uma lacuna no direcionamento de políticas intergeracionais e estabelecendo metas estratégicas de longo prazo para o Brasil, além de harmonizar as ações de curto e médio prazos com uma visão futura abrangente.\n- Designado assessor: TC Alessandra","status":"normal","assessor":"TC Alessandra","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/165555"},{"proposicao":"1258/2024","tipo":"MPV","casa":"SF","ementa":"Abre crédito extraordinário, em favor dos Ministérios da Justiça e Segurança Pública; do Meio Ambiente e Mudança do Clima; do Desenvolvimento Agrário e Agricultura Familiar; da Defesa; da Integração e do Desenvolvimento Regional; do Desenvolvimento e Assistência Social, Família e Combate à Fome; e dos Povos Indígenas, no valor de R$ 514.474.666,00, para os fins que especifica.","autor":"PR","relator":"","impacto":"- Crédito extraordinário de R$ 514,5 milhões para combater incêndios e a seca na Amazônia.\n- MD: R$ 154,7 milhões para Emprego Conjunto ou Combinado das Forças Armadas - Na Amazônia Legal.\n- EB: entre R$ 15 e R$ 20 milhões (a definir).\n- Possível dificuldade de empenhar todo o recurso até 31/12/24. Apesar de a MPV ter prazo de vigência de 18/09/24 a 16/11/24 (60 dias iniciais) e 17/11/24 a 25/02/2025 (prorrogação de 60 dias, descontados 41 dias do recesso parlamentar), o crédito extraordinário deve ser executado até 31/12/24, pois não pode ultrapassar o exercício financeiro.","tramitacao":"08/10 CMO: Recebido do relator, Dep Zé Haroldo Cathedral, relatório com voto pela aprovação da MPV, na forma proposta pelo Executivo. Quanto às 4 emendas apresentadas, o relator ofereceu voto pela inadmissibilidade.\n11/11 Mesa Diretora do CN: prorrogação do prazo para deliberação por 60 dias. Data final: 25/02/2025.\n12/11 CMO: aprovado o parecer do relator, Dep Zé Haroldo Cathedral (PSD-RR), com voto pela aprovação da MPV, na forma apresentada pelo Poder Executivo. A matéria segue para deliberação no Plenário da CD e, posteriormente, no Plenário do SF.\n12/12 Plenário CD: aprovada a Redação Final assinada pelo relator, Dep. Zé Haroldo Cathedral (PSD-RR), forma apresentada pelo executivo. A matéria vai ao Senado Federal.\n19/02 Plenário SF: aprovada a Redação Final, forma apresentada pelo executivo. A matéria vai à promulgação.\n21/02 (CN) MESA: PROMULGADA. LEI N° 15104","atuacao":"- Acompanhamento da tramitação na CMO, CD e SF.","percepcao":"A referida MPV não deve ser pautada para deliberação porque, apesar de ter prazo de vigência de 18/09/24 a 16/11/24 (60 dias iniciais) e 17/11/24 a 25/02/2025 (prorrogação de 60 dias, descontados 41 dias do recesso parlamentar), o crédito extraordinário deve ser executado até 31/12/24, pois não pode ultrapassar o exercício financeiro.\n- Designado assessor: Maj Pires","status":"concluida","assessor":"Maj Pires","link":"https://www.congressonacional.leg.br/materias/medidas-provisorias/-/mpv/165515"},{"proposicao":"3247/2024","tipo":"PL","casa":"SF","ementa":"Regulamenta a execução orçamentária e financeira, a fiscalização e o controle das transferências especiais a que se refere o art. 166-A da Constituição Federal.","autor":"Sen Styvenson Valentim (PODEMOS/RN)","relator":"","impacto":"1º OUT: 24 - Recebido do EME o parecer referente à matéria: INDIFERENTE.","tramitacao":"21/08 - Plenário do SF: o projeto vai à publicação.\n18/10 - CCJ: AGUARDANDO DESIGNAÇÃO DO RELATOR. Não foram oferecidas emendas.","atuacao":"Acompanhar.","percepcao":"- Designado assessor:","status":"normal","assessor":"","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/165120"},{"proposicao":"26/2024","tipo":"PLN","casa":"CN","ementa":"PLOA 2025: Estima a receita e fixa a despesa da União para o exercício financeiro de 2024.","autor":"PR","relator":"Sen. Angelo Coronel","impacto":"- A LOA é vital para o funcionamento eficiente, o planejamento estratégico e a prestação de contas do Exército, pois: define os recursos disponíveis para o EB, permitindo um planejamento eficiente de suas atividades, treinamentos e aquisições de equipamentos; assegura o financiamento contínuo para projetos e operações de longo prazo, permitindo que o EB mantenha sua eficiência e estado de prontidão; e, estabelece um limite de despesas para o Exército, ajudando a manter o controle financeiro e evitando gastos excessivos.\n- A tramitação do PLOA no Congresso Nacional requer muita atenção, tendo em vista que podem ocorrer cortes na proposta encaminhada pelo Executivo e mudanças nas prioridades. Essas alterações podem afetar a sustentabilidade dos meios militares e, consequentemente, o estado de prontidão permanente, bem como o processo de transformação da Força Terrestre, por meio da continuidade dos Projetos Estratégicos do Exército.\n- 1º OUT 24: o EME emitiu parecer favorável ao texto inicial apresentado pelo Executivo.","tramitacao":"30/08 - Mesa Diretora CN: Recebida a matéria.\n19/09 - Mesa Diretora CN: Recebida Msg do Presidente da República que encaminha as informações complementares relacionadas no Anexo II do PLDO 2025.\n28/11 - CMO: Aberto o prazo de 28/11 a 5/12 do sistema de elaboração de emendas (LEXOR) à LOA/2025.\n03/12 - Mesa Diretora do CN: Recebida a Msg nº 1.565/2024-PR, com proposta de modificação do PLOA 2025.\n06/12 - CMO: Aprovado o Relatório Preliminar e divulgado o avulso de emendas.\n11/12 - CMO: Aprovado o Relatório Setorial da Área Temática XIII – Defesa, apresentado pelo Dep Dagoberto Nogueira (PSDB/MS).\n12/12 - CMO: Anexado Ofício nº 263/2024, de 12.12.2024, do Deputado Paulo Alexandre Barbosa, solicitando de aporte de recurso no Relatório Geral. (Encaminhado ao Relator Geral e à Coordenação Técnica).\n20/12 - CMO: Aprovado o Relatório Final, apresentado pelo Sen Angelo Coronel (PSD/BA).\n20/12 - Plenário CN: Aprovado o Substitutivo apresentado pelo Relator, Sen Angelo Coronel (PSD/BA). A matéria vai à sanção.\n26/03 - SF-SEXPE: encaminhada a Msg nº 14/2025-CN ao PR, submetendo à sanção presidencial autógrafo do Projeto. Prazo aberto: Veto ou Sanção de PLN de 26/03 a 15/04.\n10/04/2025 - TRANSFORMADA EM NORMA JURÍDICA COM VETO PARCIAL (Lei nº 15.121 de 10/04/2025). Veto nº 10/2025, SEM IMPACTO PARA A FORÇA.","atuacao":"- Encaminhar o Projeto apresentado à 6ª SCh/EME para verificar se as demandas apresentadas pela Força ao Governo foram contempladas.\n- Acompanhar a tramitação do projeto no CN, com atenção para apresentação de emendas e pareceres.\n- Caso as demandas da Força não tenham sido atendidas na apresentação do projeto, atuar junto ao relator ou a outros parlamentares para emendar o texto.\n- Atuar na captação de recursos por meio de emendas ao PLOA, sensibilizando os parlamentares sobre as necessidades financeiras e estratégicas do EB, fornecendo informações técnicas e justificativas que embasem a alocação de recursos adicionais.\n- Manter um diálogo aberto e frequente com parlamentares para explicar as necessidades e prioridades orçamentárias do EB.\n- Fornecer informações técnicas para ajudar os legisladores a entender o impacto de diferentes níveis de financiamento nas operações do EB.\n- Defender a alocação de recursos que estejam alinhados com as metas e necessidades estratégicas do EB, incluindo a manutenção de equipamentos, treinamento de pessoal, e outros projetos prioritários.\n- Trabalhar em sintonia com outros setores da Força para garantir que as informações e demandas enviadas ao legislativo sejam precisas e coerentes.","percepcao":"- Designado assessor: Maj Pires","status":"normal","assessor":"Maj Pires","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/165205"},{"proposicao":"1466/2024","tipo":"PL","casa":"CD","ementa":"Altera o art. 68 daLei no 4.375, de 17 de agosto de 1964 - Lei do Serviço Militar, para disporsobre a distribuição dos recursos do Fundo de Serviço Militar.","autor":"Afonso Hamm - PP/RS","relator":"","impacto":"O “engessamento” da destinação dos recursos do Fundo de Serviço Militar, determinando o repasse de 50% para as Juntas do Serviço Militar, poderá acarretar na redução dos fundos geridos pelo MD, com a consequente diminuição da parte repassada às FA.","tramitacao":"- 08/05: Recebimento pela CREDN.\n- A Dep Daniela Reinehr (PL-SC) aceitou relatar.\n- A Sect da CREDEN foi informada da aceitação para distribuição.\n- Comissões: CFT e CCJC.\n- 06/12 - MESA Diretora da CD: Retirado o PL n. 1466/2024, em razão do deferimento do Requerimento n. REQ 4565/2024, nos termos do artigo 104, caput, combinado com o artigo 114, VII, ambos do RICD.","atuacao":"- Acompanhar.","percepcao":"Consta o registro de que a LOA (2024) dotou o FSM de R$ 6.544.731,00 em despesas correntes e R$ 2.780.446,00 em despesas de capital em um total de R$ 9.325.177,00. O FSM é uma Unidade Orçamentária (52903) constante da Lei Orçamentária Anual (LOA) na Ação 2872 (Mobilização para o Serviço Militar Obrigatório) do Programa 6012 (Defesa Nacional).\n- Designado assessor: TC Curvo","status":"normal","assessor":"TC Curvo","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2430328"},{"proposicao":"330/2024","tipo":"PDL","casa":"CD","ementa":"Susta os efeitos do Decreto nº 12.120, de 30 de julho de 2024, que dispõe sobre a programação orçamentária e financeira e estabelece o cronograma de execução mensal de desembolso do Poder Executivo federal para o exercício de 2024.","autor":"Fernanda Melchionna - PSOL/RS , Sâmia Bomfim - PSOL/SP , Glauber Braga - PSOL/RJ","relator":"","impacto":"A suspensão do Decreto que bloqueia R$ 15 bilhões poderá obrigar o governo a encontrar novas áreas para cortar o orçamento, podendo aumentar o impacto negativo no orçamento do EB.","tramitacao":"- 01/08/24 - MESA CD: Apresentação do PDL n. 330/2024.\n- 25/02/25 Recebimento pela CFT.","atuacao":"- Encaminhar para análise do EME e acompanhar.","percepcao":"- A justificativa para o projeto argumenta que os contingenciamentos têm efeitos políticos semelhantes ao antigo Teto de Gastos, atacando direitos sociais e programas como a valorização do salário mínimo e os pisos constitucionais da saúde e da educação.\n- Os deputados sugerem revisar a meta de déficit zero de 2024 e renegociar as metas de superávit primário até 2027 como alternativas aos cortes, além de revogar o Novo Arcabouço Fiscal, que consideram incompatível com as regras constitucionais para saúde, educação e Previdência Social.\n- Defendem uma nova lógica orçamentária que promova ativamente os direitos sociais e ambientais, alinhando-se com valores de justiça social e sustentabilidade.\n- A proposta contraria os esforços do ministro Fernando Haddad, que pretende equilibrar as contas até 2025.\n- Embora o PSOL faça parte da base de Lula no Congresso, os três deputados se abstiveram na votação da Reforma Tributária, uma medida considerada uma vitória pelo governo.\n- Designado assessor: Cap Tatiana","status":"normal","assessor":"Cap Tatiana","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2450640"},{"proposicao":"1241/2024","tipo":"MPV","casa":"CN","ementa":"Abre crédito extraordinário, em favor dos Ministérios da Justiça e Segurança Pública, do Meio Ambiente e Mudança do Clima, e da Defesa, no valor de R$ 137.638.217,00, para os fins que especifica.","autor":"PR","relator":"","impacto":"- Crédito extraordinário de R$ 137,6 milhões para reforço nas ações de prevenção e combate aos incêndios no Pantanal.\n- MD: R$ 59,7 milhões para Emprego Conjunto ou Combinado das Forças Armadas na Região Centro-Oeste (aquisição de bens de consumo e de investimento, bem como a contratação de serviços e demais necessidades referentes às atividades operacionais, de comando e controle, e de logística, para atuação na região).\n- EB: R$ 18 milhões.\n- Possível dificuldade de empenhar todo o recurso durante o período de vigência da MP: 12/07 a 9/09 (60 dias) + 10/09 a 08/11 (60 dias).","tramitacao":"- 18/07/2024 - Mesa Diretora CN: Prazo final para deliberação alterado, em virtude da não interrupção da Sessão Legislativa devido à não aprovação da LDO 2025 (\"recesso branco\").\n13/08 - CMO: Designados relator e relator revisor, o Dep José Priante (MDB/PA) e o Sen Nelsinho Trad (PSD/MS), respectivamente.\n02/09 - Mesa Diretora do CN: Prorrogação do prazo para Deliberação da Medida Provisória por 60 dias. Data final após prorrogação: 08/11/2024.\n09/11 a 17/02/2025 - Edição de Decreto Legislativo (60 dias).\n11/11 - Mesa Diretora do CN: SEM EFICÁCIA. Término do prazo de vigência, em 8 de novembro de 2024, da Medida Provisória nº 1.241, de 2024.","atuacao":"- Acompanhamento da tramitação na CMO, CD e SF.","percepcao":"- A MP possui grande apelo devido à finalidade. O Dep Dagoberto Nogueira (PSDB-MS), Relator Setorial de Defesa, iniciou sua fala na Reunião sobre Orçamento, realizada no MD no dia 10 JUL, agradecendo a atuação do MD e das Forças Armadas no controle das queimadas no Pantanal, onde esteve com as Ministras Simone Tebet e Marina Silva.\n- Designado assessor: TC Andries","status":"normal","assessor":"TC Andries","link":"https://www.congressonacional.leg.br/materias/medidas-provisorias/-/mpv/164712"},{"proposicao":"19/2024","tipo":"PLN","casa":"CN","ementa":"Altera a Lei nº 14.822, de 22 de janeiro de 2024 (LOA 2024), que estima a receita e fixa a despesa da União para o exercício financeiro de 2024.","autor":"PR","relator":"Dep. Adail Filho","impacto":"A aprovação do PLN nº 19, de 2024, que propõe a exclusão do limite de 30% para anulação de despesas discricionárias bloqueadas por meio do acréscimo do § 14 ao art. 4º da Lei nº 14.822, de 22 JAN 2024, traz riscos para o orçamento do Exército, uma vez que todas as dotações orçamentárias, referentes às despesas discricionárias, poderiam ser anuladas em prol de despesas obrigatórias do Governo Federal. Considerando o cenário atual em que foi divulgado um bloqueio de R$ 11,2 bilhões, com possíveis impactos no orçamento do Ministério da Defesa, existe a real possibilidade de que as dotações bloqueadas sejam anuladas, reduzindo, ainda mais, o já restritivo orçamento do Comando do Exército.\nDiante do exposto, o EME entende que o PLN n° 19/2024 pode trazer prejuízos para o orçamento do Exército, uma vez que abre a possibilidade de anulação de dotações orçamentárias de despesas discricionárias.\n- o PLN foi aprovado, mas foi SUPRIMIDA a exclusão do limite de 30% para anulação de despesas discricionárias bloqueadas. NÃO foi autorizado que todas as dotações orçamentárias bloqueadas (despesas discricionárias) possam ser anuladas em prol de despesas obrigatórias do Governo Federal.","tramitacao":"06/08/2024 – CMO: Distribuído ao Deputado Adail Filho, para emitir relatório.\n20/08/2024 - CMO: Encerrado o prazo regimental, ao Projeto foi apresentada 1 (uma) emenda.\n22/08/2024 - Mesa Diretora CN: Recebida MSG nº 871/2024 - PR, com proposta de modificação do PLN.\n03/09/2024 - CMO: pronta para a pauta. Recebido do relator, Dep Adail Filho, relatório com voto pela aprovação do Projeto, na forma do substitutivo apresentado, excluindo o art. 1º da proposta enviada pelo Executivo, que estava propondo a exclusão do limite de 30% para anulação de despesas discricionárias bloqueadas, por meio do acréscimo do § 14 ao art. 4º da Lei nº 14.822, de 22 JAN 2024. Quanto a emenda apresentada, recebeu voto pela REJEIÇÃO.\n16/10/2024 - CMO: apresentado pelo Relator, Dep Adail Filho, NOVO relatório, com voto pela aprovação do Projeto, na forma do substitutivo apresentado, REINCLUINDO o art. 1º da proposta enviada pelo Executivo, que inclui na Lei o § 14 no art. 4º, com o objetivo de esclarecer que o limite de anulação de despesas primárias discricionárias (30% do valor do subtítulo objeto da anulação) para suplementação de despesas, previsto no art. 4º, § 2º, inciso I, não se aplica quando a anulação de dotações envolver despesas primárias discricionárias bloqueadas nos termos do art. 69, § 2º, da LDO-2024, para suplementação de despesas primárias obrigatórias. Relatório aprovado, a matéria vai ao Plenário do CN.\n18/12 - Plenário CN: Aprovado o substitutivo com a rejeição do § 14 do art. 4º da Lei nº 14.822, de 2024, com a redação dada pelo art. 1º do PLN nº 19/2024. A matéria vai à sanção.\n23/12 - PRESIDÊNCIA DA REPÚBLICA: SANCIONADA. LEI 15052 DE 2024.","atuacao":"- Encaminhar para análise do EME e acompanhara tramitação na CMO e CN.","percepcao":"O governo está tentando obter mais liberdade para remanejamento dos recursos aprovados na LOA 2024, sem passar por nova aprovação do CN. A proposta deve enfrentou reações, mas, como ocorreu nos PLN 12 (também alterou a LOA 2024) e 13 (remanejamento dos recursos não empenhados das Emendas de Comissão), ocorreram acordos entre as lideranças e a matéria foi aprovada na CMO. Após a provável aprovação desse PLN no CN, os recursos que foram bloqueados após publicação dos Relatórios Bimestrais de Receitas e Despesas durante o ano poderão ser remanejados pelo governo, com grande probabilidade de cortes no orçamento da Força.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/164620"},{"proposicao":"25/2024","tipo":"PEC","casa":"SF","ementa":"Torna impositiva a execução das emendas\napresentadas pelas comissões permanentes da\nCâmara dos Deputados, do Senado Federal e do\nCongresso Nacional.","autor":"Sen Zequinha Marinho (PL/PA)","relator":"","impacto":"Propõe a impositividade das Emendas de Comissão (RP 8), no montante de até 0,1% (um décimo por cento) da receita corrente líquida realizada no exercício anterior.\nO Legislativo busca garantir que suas emendas orçamentárias sejam executadas de forma obrigatória, limitando o poder do Executivo de decidir sobre a alocação desses recursos. Isso fortalece o controle do Congresso sobre o orçamento e assegura que suas prioridades sejam atendidas, reduzindo a influência do governo sobre a distribuição dos recursos e evitando desvios para interesses privados.\n- Parecer do EME: desfavorável ao texto atual da PEC Nº 25/2024 (SF). \"A proposta, embora possa trazer benefícios pontuais, como a garantia de recursos adicionais para o Exército, apresenta riscos significativos ao reduzir a autonomia do Poder Executivo e potencialmente afetar negativamente a distribuição de recursos em um cenário de restrições orçamentárias.\"","tramitacao":"04/07/2024 - PLEN SF: Autuada a Proposta. Vai à publicação.\n09/07/2024 - CCJ: AGUARDANDO DESIGNAÇÃO DO RELATOR.","atuacao":"Acompanhar. Recomendação do EME: \"o monitoramento contínuo do trâmite da referida proposta, especialmente quanto a possíveis emendas que possam ser introduzidas, a fim de avaliar eventuais mudanças que possam alterar os impactos previstos e exigir uma reavaliação do posicionamento\".","percepcao":"- Propõe a impositividade das Emendas de Comissão (RP 8).\n- O autor também propos o PLP nº 46, de 2023, com a mesma intenção, mas não teve boa receptividade.\nAssessor designado: TC Alessandra.","status":"normal","assessor":"","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/164463"},{"proposicao":"1218/2024","tipo":"MPV","casa":"SF","ementa":"Abre crédito extraordinário, em favor de diversos órgãos do Poder Executivo, de Encargos Financeiros da União, e de Operações Oficiais de Crédito, no valor de R$ 12.179.438.240,00, para os fins que especifica.","autor":"PR","relator":"","impacto":"- Crédito extraordinário de R$ 12 bi para medidas emergenciais pelo estado de calamidade pública no RS.\n- MD: R$ 1,12 bi para Emp Cj FA nas Aç Proteção e Def Civil.\n- EB: R$ 644,5 mi.\n- Possível dificuldade de empenhar todo o recurso durante o período de vigência da MP (120 dias): 11/05 a 07/09.","tramitacao":"- Deliberação na CMO, CD e SF, nessa ordem, de 11/05 a 09/07 (60 dias, prorrogáveis por mais 60).\n18/07/2024 - Mesa Diretora CN: Prazo final para deliberação alterado de 21/09 para 07/09, em virtude da não interrupção da Sessão Legislativa devido à não aprovação da LDO 2025 (\"recesso branco\").\n26/08 - Plenário CD: Aprovada a Redação Final na forma apresentada pelo Executivo. A matéria vai ao Senado Federal.\n03/09 - Plenário SF: aprovada na forma apresentada pelo Executivo. À promulgação.\n06/09 - LEI Nº 14.962, DE 5 DE SETEMBRO DE 2024.","atuacao":"- Acompanhamento da tramitação na CMO, CD e SF.\n- Devido à proximidade do prazo final de vigência da MP, foram realizados contatos com as assessorias dos principais parlamentares da Bancada Gaúcha e consultores integrantes da SGM/CD, para que a matéria fosse pautada e aprovada na CD em 26/08.","percepcao":"- A MP possui grande apelo devido à finalidade, tendo sido designados rapidamente os relatores, o que demonstra grande empenho para uma tramitação acelerada.\n- O Sen Rodrigo Pacheco (PSD-MG) afirmou que o Legislativo se esforçará para votar a MP com a “celeridade” que o assunto requer.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/medidas-provisorias/-/mpv/163506"},{"proposicao":"1/122024","tipo":"PLN","casa":"CN","ementa":"Altera a Lei nº 14.822, de 22 de janeiro de 2024 (LOA 2024), que estima a receita e fixa a despesa da União para o exercício financeiro de 2024.","autor":"PR","relator":"","impacto":"Alterou a LOA 2024, autorizando a abertura de créditos suplementares sem necessidade de envio de PLN ao Congresso para as despesas primárias de que tratam os incisos IV e V do § 2º do art. 3º da LC 200, de 2023 (novo regime fiscal), que dizem respeito a: IV - as despesas...dos estabelecimentos de ensino militares federais e das demais instituições científicas, tecnológicas e de inovação, nos valores custeados com receitas próprias, ou de convênios, contratos ou instrumentos congêneres, celebrados com os demais entes federativos ou entidades privadas; e V - as despesas nos valores custeados com recursos oriundos de transferências dos demais entes federativos para a União destinados à execução direta de obras e serviços de Eng.","tramitacao":"08/05/2024 - Recebida a matéria em 07/05/2024.\n08/05/2024 - CMO: APROVADO PARECER NA COMISSÃO\n09/05/2024 - PLEN CN: Aprovada a redação final, na Câmara dos Deputados e no Senado Federal. À sanção.\n17/05/2024 - PR: Lei nº 14.856 de 17/05/2024.","atuacao":"- Aguardar posicionamento da AOFIN para verificar o que vai ser feito com o PLN 5/2024, em função da autorização aprovada neste PLN.","percepcao":"- O texto altera a LOA 2024 para direcionar recursos de crédito extraordinário ao Rio Grande do Sul. Os parlamentares alteraram o texto enviado pelo Executivo para incluir ações de saúde e assistência social. Fica autorizada a abertura de créditos suplementares para as ações mesmo que não existam impedimentos técnicos para a execução da despesa originalmente programada. Para esse atendimento, os parlamentares também poderão fazer remanejamentos parciais de suas emendas. A flexibilização também vai atingir créditos para o PAC.\n- O projeto apresentado pelo executivo contemplava duas solicitações do EB para alteração na LOA. A primeira, que foi rejeitada, era de flexibilizar o remanejamento de investimentos (GND 4) como constava na LOA 2023, pois, hoje, a alteração está limitada a 30% da dotação total de investimentos da Ação Orçamentária. A segunda alteração, que foi aprovada, é referente à autorização para a abertura de créditos suplementares sem necessidade de envio de PLN ao Congresso para as despesas primárias de que tratam os incisos IV e V do § 2º do art. 3º da Lei Complementar nº 200, de 2023 (novo regime fiscal), que dizem respeito a: IV - as despesas das universidades públicas federais, das empresas públicas da União prestadoras de serviços para hospitais universitários federais, das instituições federais de educação, ciência e tecnologia vinculadas ao Ministério da Educação, dos estabelecimentos de ensino militares federais e das demais instituições científicas, tecnológicas e de inovação, nos valores custeados com receitas próprias, ou de convênios, contratos ou instrumentos congêneres, celebrados com os demais entes federativos ou entidades privadas; e V - as despesas nos valores custeados com recursos oriundos de transferências dos demais entes federativos para a União destinados à execução direta de obras e serviços de engenharia.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/163383"},{"proposicao":"1/052024","tipo":"PLN","casa":"CN","ementa":"Abre ao Orçamento Fiscal da União, em favor do Ministério da Defesa e de Operações Oficiais de Crédito, crédito suplementar no valor de R$ 256.770.000,00, para reforço de dotações constantes da Lei Orçamentária vigente.","autor":"PR","relator":"","impacto":"- Crédito suplementar de R$ 79,77 mi para obras de convênios do EB com GO, MG e Bagé-RS.\n- Recurso para viabilizar o cumprimento do cronograma físico-financeiro e a continuidade da execução de obras realizadas por meio de convênios firmados entre o EB e estados de GO e MG e o município de Bagé-RS.\n- GO: duplicação da GO-213. MG: obras em Araguari. Bagé-RS: construção da Barragem de Arvorezinha. \n- O EB realiza as obras de cooperação para: manter-se adestrado para situações de conflito; garantir o seu reequipamento; contribuir para o desenvolvimento nacional em parceria com entidades federais, estaduais e municipais (concedentes); pronta resposta a situações de emergência.\n- A demora ou não aprovação do crédito pode paralisar ou atrasar obras essenciais, prejudicando a infraestrutura e a qualidade de vida da população em GO, MG e Bagé-RS, além de afetar o adestramento das tropas empregadas.","tramitacao":"- 30/04 Mesa Diretora CN: Anexado o Of nº 0003/2024, da Dep Adriana Ventura, que solicita ao Presidente do CN a devolução ao Executivo para as adequações necessárias. \n- 21/05 CMO: aprovado o relatório do Dep Daniel Agrobom (PL/GO), favorável à aprovação na forma proposta pelo Executivo. Inadmitida a emenda apresentada pelo Dep Adail Filho (REP/AM), conforme solicitado pela A4.\n- 29/05/2024 Plenário do CN: aprovado na CD e SF, na forma apresentada pelo Executivo. A matéria vai à sanção.\n- 13/06 - PR: Sancionada Lei 14.891, de 2024.","atuacao":"- Acompanhamento da tramitação na CMO e CN, com atenção a emendas e pareceres, para que não seja alterado o valor destinado às Obras de Cooperação.\n- Solicitado ao Dep Daniel Agrobom (PL/GO) para ser o relator.\n- Realizado contato com a AsPar Min Tur para coordenar as ações.\n- Realizado contato com o Ch Gab do Dep Júlio Arcoverde-PP/PI (Presidente CMO) para realizar a designação do relator.\n- Apresentado Of pela Dep Adriana Ventura (NOVO-SP) questionando o cumprimento da LDO 2024, que provocou a manifestação da CONORF no sentido da necessidade de complementar a exposição de motivos.\n- Acionada a AOFIN para atuar junto ao MD e a SOF no sentido de enviar uma Msg complementar esclarecendo/retificando os pontos questionados.\n- Designado relator o Dep Daniel Agrobom (PL/GO), conforme solicitado.\n- Reuniões realizadas com o relator, o Ch CONOF e o Asse da Dep Adriana Ventura.\n- Apesar de algumas questões técnicas questionadas pela Dep, foi possível esclarecer e buscar consenso sobre a importância da proposição, ressaltando seu impacto positivo para a população.","percepcao":"- O projeto foi aprovado facilmente na CMO e no CN devido aos seus objetivos, mas exigiu reuniões com o relator, consultores e a assessoria da Dep Adriana Ventura para esclarecer pontos questionados.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/163206"},{"proposicao":"1/042024","tipo":"PLN","casa":"CN","ementa":"Altera a Lei nº 14.791, de 29 de dezembro de 2023 (LDO 2024), que dispõe sobre as diretrizes para a elaboração e a execução da Lei Orçamentária de 2024","autor":"PR","relator":"","impacto":"Adequa a redação da alínea “c” do inciso III do § 1º do art. 52 da LDO 2024 visando permitir que ato do Secretário de Orçamento Federal possa alterar, justificadamente, os indicadores de RP de subtítulos constantes da LOA 2024, e de créditos adicionais, para adequar a programação às necessidades de execução, desde que mantido o valor total do subtítulo, à exceção dos indicadores de RP decorrentes de emendas parlamentares. Adicionalmente, altera o § 2º do art. 69 com a finalidade de adequar o texto acerca do bloqueio de dotações orçamentárias discricionárias abrangidas pelo Programa de Aceleração do Crescimento – Novo PAC (RP 3), de que trata a alínea “c” do inciso II do § 4º do art. 7º da LDO 2024, a fim de viabilizar o cumprimento dos limites individualizados estabelecidos na LC 200, de 2023.","tramitacao":"24/04/2024 - Mesa Diretora do CN: Recebida a matéria, aguarda despacho do Presidente do CN para envio à CMO.\n09/05/2024 - PLEN CN: Aprovada a redação final, na Câmara dos Deputados e no Senado Federal. À sanção.\n16/05/2024 - PR: Lei nº 14.855 de 16/05/2024","atuacao":"Encaminhar ao EME para análise.","percepcao":"O projeto propõe alterar o art. 16 da LDO 2024 para incluir o § 5º com o objetivo de estabelecer que o Poder Executivo Federal, no exercício financeiro de 2024, deva apoiar o fortalecimento das ações de saúde mental voltadas ao atendimento das pessoas com transtorno do espectro autista, inclusive estruturação e custeio de equipamentos de saúde pública que atendam a essa finalidade, nos termos pactuados na Comissão Intergestores Tripartite do Sistema Único de Saúde – SUS. Propõe também adequar a redação da alínea “c” do inciso III do § 1º do art. 52 da LDO 2024 visando permitir que ato do Secretário de Orçamento Federal possa alterar, justificadamente, os indicadores de RP de subtítulos constantes da Lei Orçamentária Anual de 2024, e de créditos adicionais, para adequar a programação às necessidades de execução, desde que mantido o valor total do subtítulo, à exceção dos indicadores de RP decorrentes de emendas parlamentares. Adicionalmente, altera o § 2º do art. 69 com a finalidade de adequar o texto acerca do bloqueio de dotações orçamentárias discricionárias abrangidas pelo Programa de Aceleração do Crescimento – Novo PAC (RP 3), de que trata a alínea “c” do inciso II do § 4º do art. 7º da LDO 2024, a fim de viabilizar o cumprimento dos limites individualizados estabelecidos na Lei Complementar nº 200, de 30 de agosto de 2023. Por fim, modifica a redação das alíneas “r” e “s” do inciso I do § 1º do art. 157 da LDO 2024 com o objetivo de explicitar que a divulgação em sítio eletrônico, até 30 de abril, das informações relativas à participação das Agendas Transversais e Multissetoriais no orçamento federal deve contemplar, no mínimo, as Agendas Mulher, Igualdade Racial, e Crianças e Adolescentes, incluídas, nesta última, as programações orçamentárias destinadas à prevenção da violência e à primeira infância.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/163205"},{"proposicao":"1/032024","tipo":"PLN","casa":"CN","ementa":"PLDO 2025: Dispõe sobre as diretrizes para a elaboração e a execução da Lei Orçamentária de 2025 e dá outras providências.","autor":"PR","relator":"","impacto":"- Segundo o parecer inicial do EME, o texto inicial da peça orçamentária apresentada pelo Poder Executivo não viola normas constitucionais e não apresenta inovações significativas, sendo favorável à sua aprovação, desde que atendida a emenda sugerida que inclui como despesas ressalvadas os Projetos Estratégicos: Forças Blindadas, SISFRON, ASTROS e Aviação.\n- O EME apresentou parecer desfavorável ao Relatório Preliminar, de autoria do Sen Confúcio Moura (MDB/RO), relator da proposição, no que se refere à apresentação da Projeção das Despesas com Militares Veteranos - 2024 a 2028, bem como a Projeção do Déficit das Pensões Militares - 2024 a 2028, sugerindo a possibilidade de avaliar a viabilidade de serem realizadas gestões, em coordenação com as demais Forças, junto ao presente parlamentar, com o objetivo de esclarecer as especificidades do Sistema de Proteção Social dos Militares das Forças Armadas e corrigir possíveis interpretações no relatório em tela referentes às projeções atuariais.\n- Parecer do EME sobre a Msg nº 1.210/2024 da PR: proposta visa permitir que empresas estatais dependentes, como a IMBEL, por exemplo, adquiram autonomia ao assinarem contratos de gestão com o governo, que definem objetivos e metas. Isso possibilitará que estatais atualmente dependentes, mas em processo de sustentabilidade, sejam integradas ao Orçamento de Investimentos das Empresas Estatais. Essa mudança busca promover a eficiência e a independência financeira das estatais. O EME entende que o tema possui relevância para a IMBEL. Conforme pareceres da SEF e da IMBEL, não haverá alteração das relações da UO IMBEL com o EB. Caso aprovada a proposta, permitirá flexibilidade para a gestão financeira, conferindo condições para otimizar a gestão financeira e o desenvolvimento da empresa em face da imprevisibilidade do orçamento da União. Portanto, essa situação permitirá a abertura de conta bancária, melhores aplicações financeiras, proporcionando a possibilidade da incorporação de receitas de vendas de imóveis, de financiamentos do BNDES, FINEP, conforme parecer da IMBEL.\n- Quanto à possibilidade de as estatais dependentes ganharem autonomia, o texto aprovado na CMO limitava os recursos às dotações do PLOA 2025, mas o texto final aprovado no CN permite acréscimos para quitar passivos judiciais e administrativos existentes em 2024, que devem ser quitados em até quatro anos.","tramitacao":"- 04/09 Mesa Diretora CN: Recebida a Mensagem nº 983/2024 da PR, referente ao Fundo Eleitoral.\n- 04/10 Mesa Diretora do CN: Recebida a Msg nº 1.210/2024 da PR, com proposta de modificação do PLN 3/2024.\n- 27/11 CMO: foi lido e iniciada a discussão o Relatório Preliminar com Emendas e Errata do relator.\n- 04/12 CMO - Aprovado o Relatório Preliminar e aberto prazo de apresentação de emendas, de 4 a 10/12 (18h).\n- 10/12 CMO: foram apresentadas 1.429 emendas (1.094 ao texto e 335 de inclusão de metas). EB: Emenda de META = Def AAe: 6 sistemas modernizados (CREDN); SISFRON: 2% implementado (Dep Sidney Leite-PSD/AM); Nova ESE: 50% implementada (Sen Fernando Dueire-MDB/PE).\nEB: Emenda de TEXTO = Projetos Estratégicos como despesas ressalvadas; IMBEL: pagamento de impostos como despesas obrigatórias.\n- 16/12 CMO: apresentado o Relatório Final, com os seguintes impactos para o EB: implantação do SISFRON incluída como despesa ressalvada; meta de modernização de 1 (um) Sistema de Artilharia Antiaérea; - possibilidade de estatais dependentes (Ex: IMBEL) ganhar autonomia ao assinarem contratos de gestão com o governo, tornando-se não-dependentes; mantidas como despesas obrigatórias: fardamento, movimentação, pagamento de pessoal e de benefícios, indenização de representação no exterior e fiscalização de produtos controlados.\n- 17/12 CMO: aprovado o Relatório Final.\n- 18/12 Plenário CN: aprovada a LDO 2025, a matéria vai à sanção.\n- 30/12 PR: sancionada a Lei nº 15.080, de 30 DEZ 2024. Vetada parcialmente.","atuacao":"- Acompanhamento da apresentação dos relatórios e de emendas, atuando junto ao relator para manutenção dos interesses da Força.\n- Por orientação da 6ª SCh EME, em coordenação com o MD e as demais Forças, será apresentada emenda solicitando a inclusão como despesas ressalvadas os seguintes Projetos Estratégicos: Forças Blindadas; SISFRON; ASTROS; e Aviação.\n- Será apresentada uma emenda de META referente ao Projeto Estratégico Defesa Antiaérea.-\n- A IMBEL solicitou ao EME a apresentação de uma emenda de TEXTO que propõe que as despesas referentes ao pagamento dos impostos das Empresa Estatais Dependentes integrantes do Orçamento Fiscal sejam enquadradas como despesas obrigatórias, que também será apresentada. O assunto foi apresentado ao Relator e à Consultoria de Orçamento do Senado, tendo muito boa receptividade.\n- O EME apresentou parecer desfavorável ao Relatório Preliminar, de autoria do Sen Confúcio Moura (MDB/RO), relator da proposição, no que se refere à apresentação da Projeção das Despesas com Militares Veteranos - 2024 a 2028, bem como a Projeção do Déficit das Pensões Militares - 2024 a 2028, sugerindo a possibilidade de avaliar a viabilidade de serem realizadas gestões, em coordenação com as demais Forças, junto ao presente parlamentar, com o objetivo de esclarecer as especificidades do Sistema de Proteção Social dos Militares das Forças Armadas e corrigir possíveis interpretações no relatório em tela referentes às projeções atuariais.\n- O assunto foi despachado pelo Ch/A4 com o Cmt Ex, onde foi destacado que, devido à sensibilidade do assunto, a sugestão do EME demandaria, possivelmente, uma intervenção do Ministro da Defesa, pois os dados apresentados pelo parlamentar foram retirados do PLDO 2025, apresentado pelo próprio Poder Executivo, o que ocorre anualmente dentro do item Previdência Social no referido relatório, onde são apresentadas as projeções atuariais do RGPS, RPPS, Despesas com Militares Veteranos e Pensões Militares.\n- Antes da publicação do relatório final, atuou-se junto à assessoria do Relator para reforçar o atendimento das emendas apresentadas por parlamentares e comissões solicitadas pela Força.","percepcao":"- No Anexo III, foi vetada integralmente a Seção III, que trata \"Das demais despesas ressalvadas\", incluindo a implantação do Sistema Integrado de Monitoramento de Fronteiras-SISFRON.\n- Assim como na LDO 2024, foi vetado integralmente o Anexo VIII - Prioridades e Metas, incluindo, no Programa 6112 - Defesa Nacional, a modernização de 1 (um) Sistema de Artilharia Antiaérea, dentro do Prg EE DAAe.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/163089"},{"proposicao":"68/2024","tipo":"PLP","casa":"CD","ementa":"Institui o Imposto sobre Bens e Serviços - IBS, a Contribuição Social sobre Bens e Serviços - CBS e o Imposto Seletivo - IS e dá outras providências.","autor":"PR","relator":"","impacto":"","tramitacao":"16/01/2025 Mesa Diretora CD: Transformado na Lei Complementar 214/2025. Vetado parcialmente (VET 7/2025).","atuacao":"Acompanhar.","percepcao":"- Designado assessor: Cap TATIANA","status":"normal","assessor":"Cap TATIANA","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2430143&fichaAmigavel=nao"},{"proposicao":"48/2024","tipo":"PLP","casa":"CD","ementa":"Institui e regulamenta os regimes diferenciados de tributação previstos no artigo 9º da Emenda Constitucional nº 132, de 20 de dezembro de 2023.","autor":"Dep Joaquim Passarinho (PL-PA)","relator":"","impacto":"","tramitacao":"Mesa Diretora: 12/04/2024 - Apresentação.","atuacao":"Acompanhar.","percepcao":"O Art. 2º da proposição descreve o que foi aprovado na EC 132/2023, que ficam reduzidas em 60% (sessenta por cento) as alíquotas dos\ntributos previstos nos arts. 156-A e 195, V, da Constituição Federal, incidentes nas seguintes operações:\nXIII - bens e serviços relacionados a soberania e segurança nacional, segurança da informação e segurança cibernética.\nPorém, o Art 3º descreve que, para fins de aplicação das reduções previstas nos incisos do artigo 2º, consideram-se apenas bens e serviços relacionados à segurança da informação e segurança cibernética, e não bens e serviços relacionados a soberania e segurança nacional.\n- Designado assessor: Cap TATIANA","status":"normal","assessor":"Cap TATIANA","link":"https://www.camara.leg.br/propostas-legislativas/2426526"},{"proposicao":"1209/2024","tipo":"MPV","casa":"CN","ementa":"Abre crédito extraordinário, em favor dos Ministérios da Justiça e Segurança Pública; do Meio Ambiente e Mudança do Clima; do Desenvolvimento Agrário e Agricultura Familiar; da Defesa; do Desenvolvimento e Assistência Social, Família e Combate à Fome; da Pesca e Aquicultura; dos Direitos Humanos e da Cidadania; e dos Povos Indígenas, no valor de R$ 1.062.231.956,00, para os fins que especifica.","autor":"PR","relator":"","impacto":"- Crédito extraordinário de R$ 1 bi para medidas emergenciais no território Yanomami.\n- MD: R$ 310 mi para Emp FA e Censipam.\n- EB: R$ 110,7 mi (Empenhado até 4 JUL: R$ 97,6 mi - 88,16%)\n- O EME sinalizou ser pouco provável o empenho de todo o recurso até o dia 10/07, prazo em que a MPV perde a eficácia, caso não seja aprovada.\n- Necessidade de aprovação na CMO, CD e SF antes do prazo citado, para que seja possível cumprir os objetivos da medida em questão e não se perca parte do crédito antes do término das Op.","tramitacao":"- 08/07 PLEN CD - Aprovada a Redação Final assinada pelo Dep. Murilo Galdino (REPUBLICANOS/PB). A matéria vai ao Senado Federal (MPV 1.209-A/2024).\n10/07/2024 - PLEN SF: aprovada a MP. A matéria vai à promulgação.","atuacao":"- Foi realizado contato com a assessoria do Sen Sérgio Petecão (PSD/AC) e do Dep Murillo Galdino (REPU/PB) para explicar a necessidade de aprovação da proposição dentro do prazo, bem como solicitar que fosse rejeitada a emenda da Sen Damares (REPU/DF). \n- Acompanhamento da tramitação na CD e no SF.","percepcao":"- A designação dos relatores indicou uma movimentação coordenada entre Executivo e Legislativo para acelerar a tramitação e aprovação, que avançou rapidamente na CMO.\n- A rejeição da emenda apresentada na CMO também demonstrou intenção clara de aprovar rapidamente a proposição, evitando que se transforme em um Projeto de Lei de Conversão (PLV) e necessite envio para sanção presidencial, o que atrasaria ainda mais a tramitação.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/medidas-provisorias/-/mpv/162532"},{"proposicao":"55/2023","tipo":"PEC","casa":"SF","ementa":"Altera a Constituição Federal, para estabelecer programação orçamentária mínima para o Ministério da Defesa e dispor sobre projetos estratégicos para a Defesa Nacional, e acrescenta artigo ao Ato das Disposições Constitucionais Transitórias, para estabelecer regra de transição.","autor":"Sen Carlos Portinho (PL/RJ)","relator":"","impacto":"","tramitacao":"30/10/2023 - PLEN: Autuada a Proposta de Emenda à Constituição nº 55/2023. A proposta vai à publicação.\n\n06/11/2023 - CCJ: AGUARDANDO DESIGNAÇÃO DO RELATOR.\n02/04/2025 - CCJ: MATÉRIA COM A RELATORIA: Distribuído ao Senador Randolfe Rodrigues, para emitir relatório.","atuacao":"Acompanhar.","percepcao":"- A PEC 55/2023 propõe modificar a Constituição para assegurar ao Ministério da Defesa um orçamento mínimo de 2% do PIB do ano anterior. \n- Pelo menos 35% das despesas discricionárias do MD deverão referir-se ao planejamento e à execução de projetos estratégicos para a Defesa Nacional.\n- Os projetos estratégicos para a Def Nac priorizarão a indústria nacional e contribuirão para a consolidação da Base Industrial de Def, contando com conteúdo nacional mínimo de 35%.\n- Uma regra de transição iniciará com 1,2% do PIB, aumentando 0,1% anualmente.\n- A exigência de conteúdo nacional se aplica a projetos pós-emenda, e a regra de transição começa no ano após a publicação da PEC.\n- Designado assessor: Ten Cel ALESSANDRA","status":"normal","assessor":"Ten Cel ALESSANDRA","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/160728"},{"proposicao":"44/2023","tipo":"PEC","casa":"CD","ementa":"Adiciona-se parágrafo 9ºB ao artigo 166 da Constituição Federal para permitir o emendamento em reserva, de 5% para o uso em catástrofes e emergências naturais.\nNova Ementa da Redação: Altera o art. 166 da Constituição Federal e acrescenta o art. 138 no Ato das Disposições Constitucionais Transitórias, para destinar parte dos recursos das emendas individuais e de bancadas estaduais e do orçamento da União a ações de prevenção, mitigação, preparação, resposta e recuperação de desastres.","autor":"Dep Bibo Nunes (PL-RS)","relator":"Dep. Gilson Daniel","impacto":"a PEC 44/2023, que altera o § 9º e o § 12 do artigo 166 da CF/88, e inclui os §§ 12-A, 12B e 12-C, para destinar parte dos recursos das emendas individuais, de bancadas estaduais e de Comissões ao Orçamento da União para ações de prevenção, mitigação, preparação, resposta e recuperação de desastres.\nOs §§ 9º e 12º destinam, respectivamente, 5% das Emendas Individuais (RP6) e 5% das Emendas de Bancada (RP7) para ações de prevenção, mitigação, preparação, resposta e recuperação de desastres no âmbito da Política Nacional de Proteção e Defesa Civil.\nO texto final foi ajustado para “no âmbito da Política Nacional de Proteção e Defesa Civil”, com a finalidade de que das as instituições e órgãos empregados nas referidas ações possam receber os referidos recursos, incluindo as Forças Armadas.\nFoi retirado do texto a parte que destinava 10% dos recursos alocados para as Emendas de Comissão (RP8) para o Fundo Nacional para Calamidades Públicas, Proteção e Defesa Civil (Funcap) e utilizados em ações de preparação, mitigação e prevenção de desastres, no âmbito do Sistema Nacional de Proteção e Defesa Civil, o que poderia dificultar o repasse de recursos para as Forças Armadas para o fim em questão.","tramitacao":"19/06/2024 Comissão Especial - PEC 44/23 - Aprovado o parecer com Complementação de Voto (CVO n. 1) PEC04423. A matéria vai ao Plenário da Câmara dos Deputados.\n11/07/2024 - Plenário CD - Aprovada a Redação Final assinada pelo Relator, Dep. Gilson Daniel (PODE/ES). A matéria vai ao Senado Federal (PEC 44-C/2023).\n17/07/2024 - PLEN SF: Autuada a Proposta de Emenda à Constituição nº 44/2023 proveniente da Câmara dos Deputados. A proposta vai à publicação.","atuacao":"Acompanhar.","percepcao":"Parecer do Relator (PRL n. 1 PEC04423) com Complementação de Voto (CVO n. 1) aprovado na Comissão Especial, em 19/05/2024, DESTINAR ORIGATORIAMENTE:\n- 5% do valor total destinado pelas Emendas Parlamentares Individuais e de Bancada, que serão destinados para ações de prevenção, mitigação, preparação, resposta e recuperação de desastres no âmbito da Política Nacional de Proteção e Defesa Civil.\n**5% das Emendas Individuais de DEPUTADO:\nLOA 2023: R$ 1,61 milhão \nLOA 2024: R$ 1,89 milhão \n**5% das Emendas Individuais de SENADOR:\nLOA 2023: R$ 2,95 milhões\nLOA 2024: R$ 3,48 milhões\n**5% das Emendas BANCADA ESTADUAL:\nLOA 2023: R$ 14,25 milhões\nLOA 2024: R$ 23,38 milhões\nDesignado assessor: TC Curvo","status":"normal","assessor":"TC Curvo","link":"https://www.camara.leg.br/propostas-legislativas/2388029"},{"proposicao":"1188/2023","tipo":"MPV","casa":"CN","ementa":"Abre crédito extraordinário, em favor dos Ministérios da Defesa, da Integração e do Desenvolvimento Regional e do Desenvolvimento e Assistência Social, Família e Combate à Fome, no valor de R$ 360.900.000,00, para os fins que especifica.\n- Crédito extraordinário para atender ao estado de calamidade pública decretado no Estado do Rio Grande do Sul, em decorrência da passagem do ciclone extratropical.","autor":"PR","relator":"","impacto":"","tramitacao":"20/02/2024 - CMO: aprovada.\n21/02/2024 - Plenário CD: aprovada.\n21/02/2024 - Mesa CD: apresentação do autógrafo e remassa ao SF.\n27/02/2024 - Plenário SF: aprovada.\n01/03/2024 - transformada na Lei nº 14.823, de 29 de fevereiro de 2024.","atuacao":"Acompanhar.","percepcao":"- Em resposta a uma frente fria e ao ciclone extratropical de grande intensidade que afetou a Região Sul do Brasil, especificamente o estado do RS, o Governo Federal busca providenciar recursos e ações emergenciais para os municípios atingidos. Um total de R$ 360.900.000,00 será destinado para medidas de emergência, distribuídos entre os Ministérios da Defesa, da Integração e do Desenvolvimento Regional, e do Desenvolvimento e Assistência Social, Família e Combate à Fome.\n- Deste montante, o Ministério da Defesa terá disponibilizado R$ 26.400.000,00 na Ação Orçamentária 20X7 para o Emprego Conjunto ou Combinado das Forças Armadas. A Portaria GM-MD nº 4556 determinou a ativação do Comando Operacional Conjunto “Taquari”, visando coordenar recursos das Forças Singulares em apoio à Proteção e Defesa Civil nos municípios em estado de calamidade. Entre os recursos disponibilizados estão aeronaves da Marinha, do Exército e da Força Aérea, embarcações, viaturas, militares especializados, entre outros.\n- A urgência e relevância dessa medida provisória são justificadas pela necessidade de prover assistência rápida às populações afetadas e retomar a normalidade nas áreas impactadas.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/medidas-provisorias/-/mpv/160090"},{"proposicao":"1/042024","tipo":"VET","casa":"CN","ementa":"Veto Parcial aposto ao Projeto de Lei do Congresso Nacional nº 29, de 2023 (PLOA 2024), que \"Estima a receita e fixa a despesa da União para o exercício financeiro de 2024\".","autor":"PR","relator":"","impacto":"","tramitacao":"22/01/2024 - PR: Sancionada a Lei nº 14.822, de 22 de janeiro de 2024, com veto parcial de Dotações constantes do Volume IV, conforme a Msg nº 37, de 22 de janeiro de 2024.\n- VETO 4/2024: Sobrestando a pauta a partir de 03/03/2024.\n09/05/2024 - PLEN CN: Mantido o veto aos dispositivos 04.24.001 a 24.04.030; 04.24.032 a 04.24.063; 04.24.065; 04.24.069 a 04.24.093; 04.24.095 a 04.24.110; 04.24.112 a 04.24.114; 04.24.116 a 04.24.128; 04.24.131 a 04.24.134 e 04.24.137 a 04.24.142, na Câmara dos Deputados, com o seguinte resultado: Sim 279, Não 34, Total 313; deixando de ser submetido ao Senado Federal.\nApreciação adiada do veto ao dispositivo 04.24.064.\nOs dispositivos cujo veto foi rejeitado vão à promulgação.\nSerá feita a devida comunicação ao Presidente da República.","atuacao":"- Acompanhar.","percepcao":"Mantido o veto aos dispositivos na LOA 2024 referentes ao EB:\n- 04.24.107: Aprestamento da Força (Ap à Def Civil): R$ 5.000.000 (RP 8 - CREDN);\n- 04.24.106: Implantação do Sistema de Defesa Cibernética: R$ 10.000 (RP 8 - CCAI).","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/vetos/-/veto/detalhe/16329"},{"proposicao":"29/2023","tipo":"PLN","casa":"CN","ementa":"PLOA 2024: Estima a receita e fixa a despesa da União para o exercício financeiro de 2024.","autor":"PR","relator":"","impacto":"","tramitacao":"22/12/2023 - Plenário CN: APROVADO O SUBSTITUTIVO.\n02/01/2024 - SF-SEXPE: REMETIDA À SANÇÃO.\n22/01/2024 - PR: Sancionada a Lei nº 14.822, de 22 de janeiro de 2024, com veto parcial (VETO 4/2024) de Dotações constantes do Volume IV, conforme a Msg nº 37, de 22 de janeiro de 2024.","atuacao":"- Encaminhar o Projeto apresentado à 6ª SCh/EME para verificar se as demandas apresentadas pela Força ao Governo foram contempladas.\n- Acompanhar a tramitação do projeto no CN, com atenção para apresentação de emendas e pareceres.\n- Caso as demandas da Força não tenham sido atendidas na apresentação do projeto, atuar junto ao relator ou a outros parlamentares para emendar o texto.\n- Atuar na captação de recursos por meio de emendas ao PLOA, sensibilizando os parlamentares sobre as necessidades financeiras e estratégicas do EB, fornecendo informações técnicas e justificativas que embasem a alocação de recursos adicionais.\n- Manter um diálogo aberto e frequente com parlamentares para explicar as necessidades e prioridades orçamentárias do EB.\n- Fornecer informações técnicas para ajudar os legisladores a entender o impacto de diferentes níveis de financiamento nas operações do EB.\n- Defender a alocação de recursos que estejam alinhados com as metas e necessidades estratégicas do EB, incluindo a manutenção de equipamentos, treinamento de pessoal, e outros projetos prioritários.\n- Trabalhar em sintonia com outros setores da Força para garantir que as informações e demandas enviadas ao legislativo sejam precisas e coerentes.","percepcao":"A LOA é vital para o funcionamento eficiente, o planejamento estratégico e a prestação de contas do Exército, pois:\n- Define os recursos disponíveis para o EB, permitindo um planejamento eficiente de suas atividades, treinamentos e aquisições de equipamentos;\n- Através da LOA, o EB fornece um quadro claro e público de como os fundos são alocados e usados, garantindo transparência e prestação de contas;\n- Assegura o financiamento contínuo para projetos e operações de longo prazo, permitindo que o EB mantenha sua eficiência e estado de prontidão; e\n- Estabelece um limite de despesas para o Exército, ajudando a manter o controle financeiro e evitando gastos excessivos.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/159659"},{"proposicao":"28/2023","tipo":"PLN","casa":"CN","ementa":"PPPA 2024-2027: Institui o Plano Plurianual da União para o período de 2024 a 2027.","autor":"PR","relator":"","impacto":"","tramitacao":"05/12/2023 - CMO: APROVADO PARECER NA COMISSÃO\n14/12/2023 - PLEN CN: Aprovada a redação final da matéria, na Câmara e no Senado. À sanção.\n10/01/2024 - PR: Lei nº 14.802 de 10/01/2024","atuacao":"- Encaminhar o Projeto apresentado à 6ª SCh/EME para verificar se as demandas apresentadas pela Força ao Governo foram contempladas, bem como verificar como o plano afeta o EB em termos de recursos e projetos.\n- Acompanhar a tramitação do projeto na CMO e no CN, com atenção para apresentação de emendas e pareceres, para que não seja alterado o texto apresentado, caso tenham sido atendidas as demandas da Força.\n- Caso as demandas da Força não tenham sido atendidas na apresentação do projeto pelo Executivo, atuar junto ao relator ou outros parlamentares para emendar o texto.\n- Explicar de forma clara aos parlamentares quais são as necessidades e objetivos do EB.","percepcao":"- O PPA define os fundos disponíveis para o EB, impactando investimentos e custeio (alocação de recursos).\n- O EB deve alinhar seus objetivos e projetos às metas estabelecidas no PPA (Planejamento Estratégico).\n- Projetos de longo prazo do EB precisam estar no PPA para garantir sua execução e continuidade.\n- O PPA é um documento público sujeito à revisão pelo CN, aumentando a necessidade de transparência e, consequentemente, fiscalização sobre o EB.\n- Mudanças significativas em projetos e orçamentos são complicadas sem revisar o PPA, limitando a adaptabilidade do EB a novos cenários.\n- A alocação de recursos para o EB pode ser objeto de debates políticos e sociais durante a tramitação do PPA.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/159634"},{"proposicao":"26/2023","tipo":"PLN","casa":"CN","ementa":"Abre ao Orçamento Fiscal da União, em favor do Ministério da Defesa, crédito suplementar no valor de R$ 39.700.000,00, para reforço de dotações constantes da Lei Orçamentária vigente.\nPropõe recursos decorrentes de anulação de dotação orçamentária em favor do Ministério da Defesa (100% dos recursos), para a realização de obras de cooperação, no âmbito do Comando do Exército, relativas ao convênio celebrado com o Estado de Goiás, na rodovia GO-213.","autor":"PR","relator":"","impacto":"","tramitacao":"26/09/2023 - CMO: APROVADO na forma proposta pelo Poder Executivo. Ao Projeto não foram apresentadas emendas.\n26/09/2023 - Mesa Diretora do Congresso Nacional: PRONTO PARA DELIBERAÇÃO DO PLENÁRIO\n02/10/2023 - Mesa Diretora do Congresso Nacional: Incluído em pauta da Sessão do Congresso Nacional de 04/10/2023 às 12 horas.\n04/10/2023 - Mesa Diretora do Congresso Nacional: - Aprovado, na Câmara dos Deputados e no Senado Federal, na forma proposta pelo Poder Executivo. Enviado à sanção.\n26/10/2023 - SF-SEXPE: SANCIONADA. LEI 14710 DE 2023.","atuacao":"- Solicitado ao Sen Wilder Morais (PL/GO) para que seja o relator. Pedido aceito. \n- Realizar contato com a Assessoria da Sen Daniella Ribeiro (Presidente CMO) para realizar a designação.\n- Acompanhar a tramitação do projeto na CMO e no Congresso Nacional, com atenção para apresentação de emendas e pareceres, para que não seja alterado o valor destinado à Obra de Cooperação, fruto de convênio celebrado com o Estado de Goiás, na rodovia GO-213.","percepcao":"- Obra de Cooperação, fruto de convênio celebrado com o Estado de Goiás, na rodovia GO-213, entre Morrinhos e Caldas Novas (duplicação e restauração).\n- O Exército realiza as obras de cooperação com os seguintes objetivos: manter-se adestrado para situações de conflito; garantir o seu reequipamento; contribuir para o desenvolvimento nacional em parceria com entidades federais, estaduais e municipais (concedentes); pronta resposta a situações de emergência.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/159472"},{"proposicao":"35/2023","tipo":"PEC","casa":"SF","ementa":"Altera o Sistema Tributário Nacional.","autor":"Sen Soraya Thronicke (PODEMOS/MS)","relator":"","impacto":"","tramitacao":"PLEN: 22/12/2022 - Aguardando despacho.\n08/08/2023 - A Presidência do Senado determina tramitação conjunta da PEC nº 45/2019, com as PEC nºs 110/2019 e 46/2022, por tratarem de tema correlato.\n09/08/2023 - CCJ: Distribuído ao Senador Eduardo Braga, para emitir relatório.","atuacao":"Acompanhar.","percepcao":"Industria Nacional de Defesa.\nA proposta simplifica e racionaliza a tributação sobre a comercialização de bens e a prestação de serviços.\nDesignado assessor: TC ALESSANDRA","status":"normal","assessor":"TC ALESSANDRA","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/159093"},{"proposicao":"1183/2023","tipo":"MPV","casa":"CN","ementa":"Abre crédito extraordinário, em favor do Ministério da Defesa, no valor de R$ 140.230.300,00. Visa ao atendimento de despesas das Forças Armadas em apoio a medidas emergenciais na Terra Indígena Yanomami, no escopo da Arguição de Descumprimento de Preceito Fundamental (ADPF) nº 709/2020 e do Plano de Trabalho do Comitê de Coordenação Nacional para Enfrentamento à Desassistência Sanitária das Populações em Território Yanomami, instituído pelo Decreto nº 11.384, de 20 de janeiro de 2023, segundo o Ministério da Defesa, é importante destacar que a presente demanda decorre da Decisão proferida pelo Supremo Tribunal Federal - STF.","autor":"PR","relator":"","impacto":"","tramitacao":"02/08/2023 - Mesa: Calendário de tramitação da Medida Provisória:\n- Deliberação: de 02/08/2023 a 30/09/2023\n- Apresentação de Emendas: de 02/08/2023 a 08/08/2023 (Res. 1/2002-CN)\n- Regime de urgência, obstruindo a pauta a partir de: 16/09/2023 (46º dia)\n* A Comissão Mista deve, obrigatoriamente, emitir parecer antes de a matéria ser submetida aos Plenários da CD e do Senado (art. 62, § 9º - CF / Ação Direta de Inconstitucionalidade nº 4.029 - DOU de 16/03/2012)\n* As emendas poderão ser enviadas pelo sistema até as 23h59 do dia 08/08/2023.\n09/08/2023 - CMO: Encerrado o prazo regimental, foram apresentadas 2 (duas) emendas. Conforme Resolução nº 1/2002 do CN.\n29/09/2023 - SF-SLCN: Ação: Prorrogação do prazo para Deliberação por 60 dias. Data final após prorrogação: 29/11/2023.\n30/11/2023 - Mesa Diretora CN: SEM EFICÁCIA. Término do prazo de vigência, em 29 NOV 2023.","atuacao":"Acompanhar.","percepcao":"O Ministro da Defesa autorizou o uso temporário das Forças Armadas para combater problemas de saúde e garimpo ilegal no Território Yanomami, inicialmente alocando R$ 135,474,000 (MP 1168/2023). Com o progresso das operações, viu-se a necessidade de expandir o escopo das Forças Armadas para incluir ações mais agressivas contra os garimpeiros e organizações criminosas na região.Uma nova operação, chamada \"Operação Ágata Fronteira Norte\", foi ativada, substituindo a anterior, e um decreto subsequente expandiu o papel das Forças Armadas para também abordar delitos transfronteiriços e ambientais. A estimativa é de que serão necessários recursos adicionais no valor de R$ 140,230,300 (MP 1183/2023) até o fim de julho de 2023 para cobrir os custos dessa expansão, incluindo aquisição de bens de consumo, contratação de serviços e outras necessidades específicas para as ações no Território Yanomami.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/medidas-provisorias/-/mpv/158879"},{"proposicao":"111/2023","tipo":"PLP","casa":"CD","ementa":"Institui regime fiscal sustentável para garantir a estabilidade macroeconômica do País e criar as condições adequadas ao crescimento socioeconômico, nos termos do disposto no art. 6º da Emenda à Constituição nº 126, de 21 de dezembro de 2022.","autor":"Dep Mendonça Filho (UNIÃO-PE)","relator":"","impacto":"","tramitacao":"Mesa Diretora: 16/05/2023 - Apresentação.\nMesa Diretora: 16/05/2023 - Apresentação do REQ n. 1559/2023 (Requerimento de Apensação), pelo Dep Mendonça Filho (UNIÃO/PE), que \"Requer que o PLP 111/2023 seja apensado ao PLP 93/2023 \"","atuacao":"Encaminhar ao EME para análise. Acompanhar.","percepcao":"- MANTIDO (EC 126/22):\nArt. 3º Ficam estabelecidos (...) os limites individualizados (...) relativas a despesas primárias:\n§ 2º Não se incluem nos limites estabelecidos neste artigo:\nVII - as despesas custeadas com recursos oriundos de transferências dos demais entes federativos para a União destinados à execução direta de obras e serviços de engenharia;\n- RETIRADO no texto inicial e INSERIDO no PRLP n. 1: \nArt. 3º Ficam estabelecidos (...) os limites individualizados (...) relativas a despesas primárias:\n§ 2º Não se incluem nos limites estabelecidos neste artigo:\nV - as despesas das universidades públicas federais, das empresas públicas da União prestadoras de serviços para hospitais universitários federais e das instituições federais de educação, ciência e tecnologia, vinculadas ao Ministério da Educação, dos estabelecimentos de ensino militares federais, e das demais instituições científicas, tecnológicas e de inovação, nos valores custeados com receitas próprias, ou de convênios, contratos ou outras fontes, celebrados com os demais entes federativos ou entidades privadas;","status":"normal","assessor":"","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2362478"},{"proposicao":"1451/2023","tipo":"PL","casa":"CD","ementa":"Inclui o artigo 24-K na Lei nº 13.954, de 16 de dezembro de 2019 – Lei que reestrutura a carreira militar e dispõe sobre o Sistema de Proteção Social dos Militares, para estabelecer proibição aos entes federativos de aplicar a alíquota \nprevidenciária aos militares inativos, sem que esteja cumprindo a integralidade e paridade dos vencimentos, bem como, o pagamento exclusivamente por subsídio.","autor":"Dep Cabo Gilberto Silva - PL/PB","relator":"","impacto":"","tramitacao":"Apresentado, 27/03/2023.\nMESA: 11/05/2023 - Às comissões:\nCSPCCO: 07/07/2023 - Encerrado o prazo de 5 sessões para apresentação de emendas ao substitutivo (de 28/06/2023 a 07/07/2023). Não foram apresentadas emendas ao substitutivo.\n01/08/2023 - Lido o Parecer pelo Relator. Aprovado o Parecer (acolhida a retirada do trecho que fazia menção à Lei 13.954/19).","atuacao":"Foi trabalhada, junto ao relator, a retirada do trecho que fazia menção à Lei 13.954/19, acolhida no substitutivo aprovado na CSPCCO em 01/08/2023.","percepcao":"Pode abrir espaço para alterações na Lei 13.954/2019.\nDesignado assessor: TC CURVO\n26/06/2023 - PRL n. 1 CSPCCO (Parecer do Relator): \"Além disso, o art. 24-K deve ser inserido no bojo do Decreto-lei nº 667, de 2 de julho de 1969, que reorganiza as Polícias Militares e os Corpos de Bombeiros Militares dos Estados, dos Territórios e do Distrito Federal e dá outras providências, e não na Lei nº 13.954, de 16 de dezembro de 2019, uma vez que se trata de legislação alteradora.\"","status":"normal","assessor":"TC CURVO","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2353684"},{"proposicao":"1/052023","tipo":"PLN","casa":"CN","ementa":"Abre ao Orçamento da Seguridade Social da União, em favor do Ministério da Saúde, crédito especial no valor de R$ 7.300.000.000,00, para o fim que especifica.\nProjeto visa incluir nova categoria de programação, no âmbito do Fundo Nacional de Saúde, a fim de possibilitar o atendimento de despesas com o piso nacional do enfermeiro, do técnico de enfermagem, do auxiliar de enfermagem e da parteira, previsto inicialmente pela Emenda Constitucional nº 124, de 14 de julho de 2022, e regulamentado pela Lei nº 14.434, de 4 de agosto de 2022.","autor":"PR","relator":"","impacto":"","tramitacao":"Último estado: 26/04/2023 - APROVADO.\nAprovado, na Câmara dos Deputados, nos termos do parecer da CMO, favorável ao projeto na forma apresentada pelo Poder Executivo, com o voto contrário do Partido NOVO.\nAprovado, no Senado Federal, nos termos do parecer da CMO, favorável ao projeto na forma apresentada pelo Poder Executivo.\nSANCIONADA Lei 14.581/23 em 11/05/23.","atuacao":"Acompanhar avulso de emendas e parecer da relatora para ver se aparece alguma indicação de utilização o superávit financeiro das fontes de recursos dos fundos públicos do Poder Executivo (Art. 3º da EC 127/22).","percepcao":"No texto arovado o pleito será viabilizado à conta da incorporação de superávit financeiro apurado no balanço patrimonial do exercício de 2022, referente à\nCapitalização do Fundo Social (Art. 4º da EC 127/22), não indicando utilização do superávit financeiro das fontes de recursos dos fundos públicos do Poder Executivo (Art. 3º da EC 127/22).","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/157016"},{"proposicao":"93/2023","tipo":"PLP","casa":"CD","ementa":"Institui regime fiscal sustentável para garantir a estabilidade macroeconômica do País e criar as condições adequadas ao crescimento socioeconômico, com fundamento no art. 6º da Emenda Constitucional nº 126, de 21 de dezembro de 2022, e no inciso VIII do caput e no parágrafo único do art. 163 da Constituição Federal; e altera a Lei Complementar nº 101, de 4 de maio de 2000 (Lei de Responsabilidade Fiscal), e a Lei nº 10.633, de 27 de dezembro de 2002.","autor":"PR","relator":"Dep. Claudio Cajado","impacto":"","tramitacao":"Plenário Senado Federal : 21/06/2023 - APROVADA, a matéria retorna à Câmara dos Deputados.\nMesa Diretora Câmara dos Deputados: 21/06/2023 - Recebido o Of nº 495/23 do Senado Federal, que comunica a aprovação, em revisão e com emendas, do PLP 93/2023.\nPlenário Câmara dos Deputados: 22/08/2023 - Aprovada a Redação Final assinada pelo Relator, Dep. Claudio Cajado (PP-BA). A matéria vai à sanção (PLP 93-D/2023).\nMesa Diretora Câmara dos Deputados: 30/08/2023 - Transformado na Lei Complementar 200/2023.DOU 31/08/23 PÁG 01 COL 02. Vetado parcialmente (não afeta os textos trabalhados pela Assessoria). (MSC 431/23-PE). Razões do veto: DOU 30/08/23 PÁG 13 COL 01.","atuacao":"Encaminhado ao EME para análise.\nInserido o texto sobre os Estabelecimentos de Ensino Militares .\nAcompanhar nova votação na CD na 1ª semana de julho.","percepcao":"- Aprovado o texto trabalhado pela Assessoria:\n\"Art. 3º.........................................................................................................\n§ 2º Não se incluem na base de cálculo e nos limites estabelecidos neste artigo:\nIV - as despesas das universidades públicas federais, das empresas públicas da União prestadoras de serviços para hospitais universitários federais, das instituições federais de educação, ciência e tecnologia vinculadas ao Ministério da Educação, DOS ESTABELECIMENTOS DE ENSINO MILITARES FEDERAIS e das demais instituições científicas, tecnológicas e de inovação, nos valores custeados com receitas próprias, ou de convênios, contratos ou instrumentos congêneres, celebrados com os demais entes federativos ou entidades privadas;\nV - as despesas nos valores custeados com recursos oriundos de transferências dos demais entes federativos para a União destinados à EXECUÇÃO DIRETA DE OBRAS E SERVIÇOS DE ENGENHARIA;\"","status":"normal","assessor":"","link":"https://www.camara.leg.br/propostas-legislativas/2357053"},{"proposicao":"1/012024","tipo":"VET","casa":"CN","ementa":"Veto Parcial aposto ao Projeto de Lei do Congresso Nacional nº 4, de 2023 (PLDO 2024), que \"Dispõe sobre as diretrizes para a elaboração e a execução da Lei Orçamentária de 2024 e dá outras providências\".","autor":"PR","relator":"","impacto":"- 310 dispositivos vetados, com destaque para o Cronograma de Pagamento de Emendas.\n- Foi vetado integralmente o Anexo de Prioridades e Metas e, por consequência, as seguintes metas que impactam no EB: Aquisição de 1 Helcp para Emp das FA; Aquisição de 33 Bld; Implantação de 3% do SISFRON; e 1 OM do EB instalada/adequada (construção da Nova ESE).\n- O Governo vetou todo o referido anexo para ter mais flexibilidade de executar outras prioridades. Mas, mesmo que o veto seja mantido, não quer dizer que as metas vetadas não serão executadas.\n- A derrubada do veto ao cronograma pode reduzir o prazo de empenho dos recursos recebidos por emendas pelo EB.","tramitacao":"- 28/05 - Plen CN: mantido o veto Cronograma de Empenho e Pagamento de Emendas e metas que impactam no EB.","atuacao":"Acompanhar. A manutenção do veto ao Cronograma de Pagamento de Emendas e às metas referentes ao EB não afeta diretamente o orçamento da Força.","percepcao":"- Foi vetado integralmente o Anexo de Metas e Prioridades (Inciso VII do caput do art. 186 e Anexo VII), com a justificativa: “Veto por arrastamento, em razão da contrariedade ao interesse público que maculou o art. 4º do Projeto de Lei, cujo teor ampliaria o rol das prioridades da Administração Pública federal para 2024, de modo a dispersar os esforços do Governo para melhorar a execução, o monitoramento e o controle das prioridades já elencadas”.\n- Dentro do Programa 6112 - DEFESA NACIONAL, foram vetadas os seguintes dispositivos (metas) relacionados ao EB:\n* 01.24.296 - Aquisição de 1 (um) Helicóptero para Emprego das Forças Armadas;\n* 01.24.298 - Aquisição de 33 (trinta e três) blindados para o Projeto Forças Blindadas.\n* 01.24.299 - Implantação de 3% (três por cento) SISFRON;\n* 01.24.301 - 1 (uma) Organização Militar do Exército Brasileiro instalada/adequada (Construção da Nova ESE).\n- Foi vetado o Cronograma de pagamento de emendas:\n01.24.028 - inciso I do § 7º do art. 82 (Ocultar texto do dispositivo vetado) empenhar a despesa até 30 dias contados do término do prazo previsto no inciso III do caput; e\n- O CN vinha sinalizando a tendência de derrubar o veto, principalmente por causa do dispositivo que aborda o cronograma de pagamento das emendas. \n- A derrubada do veto seria uma forma de enfraquecer o poder de barganha do Executivo nas votações de maior interesse do mesmo, por meio da liberação do recurso e pagamento das emendas parlamentares. \n- No entanto, o governo propôs ao legislativo um acordo que inclui um cronograma próprio para a liberação das emendas, que estava atrasado, mas teve um avanço significativo em abril, o que manteve o veto.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/vetos/-/veto/detalhe/16249"},{"proposicao":"1/042023","tipo":"PLN","casa":"CN","ementa":"PLDO 2024: Dispõe sobre as diretrizes para a elaboração e a execução da Lei Orçamentária de 2024 e dá outras providências.","autor":"PR","relator":"","impacto":"","tramitacao":"19/12/2023 PLEN - Plenário do Congresso Nacional\nSituação: APROVADO O SUBSTITUTIVO.\n02/01/2024 - Presidência da República: SANCIONADA. Lei 14791, de 29 de Dezembro de 2023. (vetada parcialmente: MSG 754 de 2023). DOU 02/01/2024 - Seção I - págs. 2 e 73.\n03/01/2024 - Mesa Diretora do Congresso Nacional: VET 1/2024.","atuacao":"Encaminhar ao EME para análise.","percepcao":"a. Mantidas como despesas obrigatórias para o Exército: 1) Fiscalização de produtos controlados; 2) Fardamento; 3) Alimentação; 4) Movimentação de militares; e 5) Pagamento de pessoal e benefícios.\nb. Emendas apresentadas pelo EB e aprovadas:\n1) Acréscimo de 2% de execução da implantação do SISFRON. APROVADA com a meta de 3%.\n2) Aquisição de 99 blindados para o Projeto Forças Blindadas. APROVADA PARCIALMENTE com a meta de 33 blindados.\nc. Emendas apresentadas por parlamentares e aprovadas, com impacto positivo na Força:\n1) Sen Fernando Dueire (MDB/PE): Implantação da Escola de Sargentos do Exército em Pernambuco. APROVADA com a meta de 1 OM Instalada/Adequada.\n2) Dep Pedro Aihara (PATRIOTA/MG): Aquisição de 4 helicópteros para Emprego das Forças Armadas. APROVADA PARCIALMENTE com a meta de aquisição de 1 helicóptero.\nd. Emendas apresentadas pelo EB e rejeitadas:\n1) Incluir como Despesas Ressalvadas os Projetos Estratégicos do Exército. REJEITADA.\n2) Tornar uma despesa obrigatória a ajuda de custo para auxílio-moradia no exterior. REJEITADA.\n3) Não exigência do encaminhamento de PLN relativo a créditos suplementares quando se tratar de despesas nos valores custeados com recursos oriundos de transferências dos demais entes federativos para a União destinados à execução direta de obras e serviços de engenharia. REJEITADA.\n4) Não exigência do encaminhamento de PLN relativo a créditos suplementares quando se tratar de despesas dos estabelecimentos de ensino militares federais. REJEITADA.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/156890"},{"proposicao":"1/022023","tipo":"PLN","casa":"CN","ementa":"Altera o Anexo V à Lei no 14.535, de 17 de janeiro de 2023, que estima a receita e fixa a despesa da União para o exercício financeiro de 2023.\nA alteração proporciona a autorização na LOA para a concessão de reajuste aos servidores públicos federais, conforme pactuação realizada junto às entidades representativas das servidoras e servidores públicos federais do poder executivo civil no âmbito da Mesa Nacional de Negociação Permanente – MNNP.","autor":"PR","relator":"","impacto":"","tramitacao":"Último estado: 26/04/2023 - APROVADO O SUBSTITUTIVO\nAprovado o Projeto, na CD, nos termos do parecer da CMO, favorável ao projeto na forma do substitutivo. Aprovado o Projeto, no Senado, nos termos do parecer da CMO, favorável ao projeto na forma do substitutivo. \nSANCIONADA. Lei 14.563/2023 em 28/04/23. VET 8/2023 - Parcial (3 dispositivos vetados) - Remuneração dos cargos da ANM, dos militares e bombeiros dos ex-Territórios e do Antigo Estado da Guanabara.","atuacao":"Acompanhar.","percepcao":"Não incluiu militares federais.","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/pesquisa/-/materia/156659"},{"proposicao":"1168/2023","tipo":"MPV","casa":"CN","ementa":"Abre crédito extraordinário, em favor dos Ministérios da Justiça e Segurança Pública; do Meio Ambiente e Mudança do Clima; da Defesa; do Desenvolvimento e Assistência Social, Família e Combate à Fome; e dos Povos Indígenas, no valor de R$ 640.074.000,00, para o fim que especifica.","autor":"PR","relator":"","impacto":"","tramitacao":"Último estado: 01/08/2023 - Mesa - SEM EFICÁCIA (Encerramento do prazo de vigência da referida Medida. A matéria aguarda edição de decreto legislativo)\nMESA do CN: 29/09/2023: Esgotou-se o prazo previsto no § 11 do art. 62 da Constituição Federal e no § 2º do art. 11 da Resolução nº 1, de 2002-CN, sem edição de decreto legislativo que discipline as relações jurídicas decorrentes da MP nº 1.168, de 2023, cuja vigência encerrou-se em 31-07-2023, por perda de eficácia sem apreciação pelas Casas do CN.","atuacao":"Acompanhar.","percepcao":"Abre crédito extraordinário de R$ 135.474.000,00 para o MD - Emprego das Forças Armadas em Apoio a Ações Emergenciais em Terras Indígenas","status":"normal","assessor":"","link":"https://www.congressonacional.leg.br/materias/medidas-provisorias/-/mpv/156682"},{"proposicao":"77/2023","tipo":"PDL","casa":"CD","ementa":"Susta, nos termos do art. 49, V, da Constituição Federal, a aplicação da Portaria Interministerial MPO/MGI/SRI – PR nº 1, de 3 de março de 2023, que “dispõe sobre procedimentos e prazos para operacionalização das emendas individuais, de bancada estadual, de comissão e de comissão mista permanente e superação de impedimentos de ordem técnica, em atendimento ao disposto nos arts. 166, §§ 9º a 20, e 166-A da Constituição, nos arts. 69, 71 a 82 da Lei nº 14.436, de 9 de agosto de 2022 e art. 4º, § 7º, da Lei nº 14.535, de 17 de janeiro de 2023, e dá outras providências”.","autor":"Dep Any Ortiz - CIDADANIA/RS","relator":"","impacto":"","tramitacao":"16/03/2023 - Plenário: apresentação.\n03/07/2023 - Mesa: à CFT e CCJC.\n04/07/2023 - CFT: Recebimento.","atuacao":"Acompanhar.","percepcao":"Propõe sustar a Portaria que regula a operacionalização das Emendas Individuais ao PLOA 23.","status":"normal","assessor":"","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2351658"},{"proposicao":"62/2023","tipo":"PLP","casa":"CD","ementa":"Estabelece Novo Arcabouço Fiscal da União voltado para a sustentabilidade da dívida, a integração das regras fiscais, e dá outras providências, com amparo no Capítulo II do Título II da Constituição, inciso VIII e parágrafo único do art. 163, art. 164-A e § 2 do art. 165 e no art. 9º da Emenda Constitucional nº 126, de 2022.","autor":"Dep Pedro Paulo - PSD/RJ","relator":"","impacto":"","tramitacao":"Mesa Diretora: Apresentação (16/03/2023)\nMesa Diretora: 02/06/2023 - Apense-se à(ao) PLP-25/2022.","atuacao":"Acompanhar.","percepcao":"Caso seja publicada, revoga o inciso I, do § 6º-A, do Art 107 dos ADCT, incluído pela EC 126/2022 que \"Não se incluem no limite estabelecido no inciso I do caput deste artigo, a partir do exercício financeiro de 2023: \nIII - despesas custeadas com recursos oriundos de transferências dos demais entes da Federação para a União destinados à execução direta de obras e serviços de engenharia.\"","status":"normal","assessor":"","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2351651"},{"proposicao":"46/2023","tipo":"PLP","casa":"SF","ementa":"Altera a Lei nº 4.320, de 17 de março de 1964, que \"Estatui Normas Gerais de Direito Financeiro para elaboração e controle dos orçamentos e balanços da União, dos Estados, dos Municípios e do Distrito Federal\", para tornar impositiva a execução das emendas apresentadas pelas comissões permanentes da Câmara dos Deputados, do Senado Federal e do Congresso Nacional.","autor":"Sen Zequinha Marinho (PL/PA)","relator":"","impacto":"- Propõe a impositividade das Emendas de Comissão (RP 8), no montante de até 1% (um por cento) da receita corrente líquida realizada no exercício anterior, semelhante ao que já ocorre com as Emendas de Bancadas Estaduais.","tramitacao":"05/10/2023 - CAE: O relator, senador Mauro Carvalho Junior, apresentou relatório favorável ao projeto.\n31/10/2023 - CAE: A comissão aprova a apresentação ao Plenário do Requerimento nº 188/2023-CAE, para audiência da Comissão de Constituição, Justiça e Cidadania. Aprovado, também, o Requerimento nº 189/2023-CAE, para a realização de audiência pública para instrução da matéria.\n31/10/2023 - CAE: o relator apresentou novo relatório, favorável ao projeto, com a Emenda nº 1.","atuacao":"Acompanhar.","percepcao":"- Propõe a impositividade das Emendas de Comissão (RP 8).\n- Parecer do relator na CAE: O parecer é favorável à aprovação do PLP nº 46, de 2023. O relator argumenta que tornar impositiva a execução das emendas apresentadas pelas comissões permanentes é uma progressão lógica das emendas parlamentares, tendo em vista as mudanças anteriores que tornaram impositivas as emendas individuais e de bancada. Ele também destaca que a medida aumentará o controle do Legislativo sobre o Orçamento, restringindo a discricionariedade do Executivo.","status":"normal","assessor":"","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/156131"},{"proposicao":"25/2022","tipo":"PLP","casa":"CD","ementa":"Estabelece normas gerais de finanças públicas voltadas para a elaboração de planos e orçamentos, gestão e controle orçamentário, financeiro e patrimonial e criação e funcionamento de fundos da Administração Pública, altera dispositivos da Lei Complementar nº 101, de 4 de maio de 2000, a fim de fortalecer a gestão fiscal responsável e dá outras providências.","autor":"Felipe Rigoni - UNIÃO/ES, Tabata Amaral - PSB/SP","relator":"","impacto":"","tramitacao":"Mesa Diretora: Apresentação (16/03/2022)\nMesa Diretora: 24/03/2022 - Apense-se à(ao) PLP-295/2016.\nMesa Diretora: 02/06/2023 - Apense-se à(ao) PLP-62/2023.\nMesa Diretora: 30/06/2023 - Apense-se a este(a) o(a) PLP-111/2023.\nMesa Diretora: 05/07/2023 - Apense-se a este(a) o(a) PLP-122/2023.","atuacao":"Acompanhar.","percepcao":"Proposta de Nova Lei Complementar de Finanças Públicas.","status":"normal","assessor":"","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2318054"},{"proposicao":"294/2022","tipo":"PL","casa":"CD","ementa":"Autoriza a Criação do FUNDO NACIONAL DE APOIO A SITUAÇÕES DE DESASTRE, CALAMIDADE E EMERGENCIA.","autor":"Dep Reginaldo Lopes - PT/MG","relator":"Dep. Daniela Reinehr","impacto":"","tramitacao":"13/04/2023: Integração Nacional e Desenvolvimento Regional (CINDRE ) - Designada Relatora, Dep. Daniela Reinehr (PL-SC)\n14/04/2023: Integração Nacional e Desenvolvimento Regional ( CINDRE ) - Reabertura do Prazo para Emendas ao Projeto - Art. 166 do RICD (5 sessões a partir de 17/04/2023).\n27/04/2023: Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 14/04/2023 a 27/04/2023). Não foram apresentadas emendas.","atuacao":"Acompanhar.","percepcao":"Possibilidade de emendas propondo a utilização dos fundos vinculados ao Ministério da Defesa.\n\"Art. 2º Constituirão recursos do FUNDEC:\nVI - outros recursos que lhe forem destinados por lei;\nVII - recursos de outras fontes.\"","status":"normal","assessor":"","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2314693"},{"proposicao":"46/2022","tipo":"PEC","casa":"SF","ementa":"Altera o Sistema Tributário Nacional e dá outras providências.","autor":"Sen Oriovisto Guimarães\n (PODEMOS/PR)","relator":"","impacto":"","tramitacao":"PLEN: 22/12/2022 - Aguardando despacho.\n08/08/2023 - A Presidência do Senado determina tramitação conjunta da PEC nº 45/2019, com as PEC nºs 110/2019 e 46/2022, por tratarem de tema correlato.\n08/11/2023 SF-SEADI - Secretaria de Atas e Diários: PREJUDICADA. A matéria vai ao arquivo.","atuacao":"Acompanhar.","percepcao":"- Em substituição ao RETID, foi incluído o seguinte texto:\n\"Art. 9º A lei complementar que instituir o imposto de que trata o art. 156-A e a contribuição de que trata o art. 195, V, ambos da Constituição Federal, poderá prever os regimes diferenciados de tributação de que trata este artigo, desde que sejam uniformes em todo o território nacional e sejam realizados os respectivos ajustes nas alíquotas de referência com vistas a reequilibrar a arrecadação da esfera federativa.\n§ 1º A lei complementar definirá as operações beneficiadas com redução de 60% (sessenta por cento) das alíquotas dos tributos de que trata o caput entre as relativas aos seguintes bens e serviços:\nXIIII – bens e serviços relacionados a soberania e segurança nacional, segurança da informação e segurança cibernética;\"\n- Designada assessora: Ten Cel ALESSANDRA.","status":"normal","assessor":"","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/155612"},{"proposicao":"17/2022","tipo":"PEC","casa":"CD","ementa":"Visa a atualização e capacitação tecnológica das Forças Armadas, alterando o art. 167 da Constituição Federal, para retirar a limitação de dotações consignadas ao orçamento das Forças Armadas e acrescentando o art. 101 ao Ato das Disposições Constitucionais Transitórias, para vedar, quaisquer limitações à execução das dotações.","autor":"Dep Luiz Philippe de Orleans e Bragança - PL/SP e outros","relator":"","impacto":"Caso aprovada, a PEC nº 17/2022 trará impactos positivos e estruturantes para o EB, ao assegurar previsibilidade e estabilidade para o financiamento das despesas discricionárias voltadas à atualização e capacitação tecnológica da Força. A proposta proíbe a limitação de empenho e movimentação financeira desses recursos e estabelece, por dez anos renováveis, a vedação a contingenciamentos em projetos estratégicos de defesa, com garantia de piso anual de 0,5% do PIB orçado. Isso permitirá ao Exército planejar e executar, com maior segurança, iniciativas como o SISFRON, o Programa Guarani e o ASTROS, viabilizando a antecipação de entregas, a obtenção das Capacidades Militares Terrestres (CMT) e o fortalecimento da Base Industrial de Defesa, que depende de investimentos contínuos e de longo prazo. A medida reforça o estado de prontidão da Força Terrestre, evita descontinuidade nos investimentos plurianuais e contribui para a manutenção de pessoal qualificado, mitigando riscos de evasão de profissionais especializados e garantindo o cumprimento dos cronogramas pactuados com fornecedores nacionais e internacionais.","tramitacao":"CCJC: Recebimento pela CCJC, 20/06/2022.\nCCJC: 23/04/2024 - Apresentação do PRL n. 1 CCJC (Parecer do Relator), pela Dep Bia Kicis (PL/DF), pela admissibilidade.\nComissão Especial:\nPLEN:","atuacao":"Acompanhar.","percepcao":"A PEC 17/2022 altera a Constituição para proibir qualquer limitação ou contingenciamento das dotações orçamentárias discricionárias do Ministério da Defesa e das Forças Armadas, assegurando que, por no mínimo 10 anos, renováveis, os recursos discricionários destinados a projetos estratégicos de defesa (nas áreas terrestre, marítima, aérea, aeroespacial, cibernética e nuclear) não poderão ser bloqueados e deverão corresponder, anualmente, a no mínimo 0,5% do PIB orçado. A proposta também obriga o governo a incluir nas leis orçamentárias os valores integrais para honrar contratos de financiamento externo já firmados, com contrapartidas, e a realizar os ajustes necessários em até seis meses após a promulgação.\nDesignado assessor: Ten Cel CURVO","status":"normal","assessor":"Ten Cel CURVO","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2329063"},{"proposicao":"2500/2021","tipo":"PL","casa":"CD","ementa":"Disciplina, no âmbito da União, a submissão ao limite remuneratório de que tratam o inciso XI do caput do art. 37 da Constituição Federal e os §§ 9º e 12 do mesmo dispositivo, quando efetivados em moeda estrangeira.","autor":"Dep Aécio Neves - PSDB/MG","relator":"","impacto":"","tramitacao":"CASP: recebido, 04/04/2023.\nCFT:\nCCJC:","atuacao":"Acompanhar.","percepcao":"Regulamenta o limite remuneratório em moeda estrangeira, por meio da aplicação do critério de paridade de poder de compra entre o real e o dólar norte-americano.\nDesignado assessor: Cel SIDNEY VIANA","status":"normal","assessor":"Cel SIDNEY VIANA","link":""},{"proposicao":"1127/2021","tipo":"PDL","casa":"CD","ementa":"Aprova os textos da Política Nacional de Defesa (PND), da Estratégia Nacional de Defesa (END) e do Livro Branco de Defesa Nacional (LBDN).","autor":"SF-CCAI","relator":"","impacto":"","tramitacao":"02/06/2022 - PLEN SF - Aprovado.\n15/05/2024 - PLEN CD: Aprovado. A matéria vai à promulgação (PDL 1.127-A/2021). 23/05/2024 - Transformado no Decreto Legislativo 61/2024.","atuacao":"Acompanhar.","percepcao":"**AED-14 Buscar a destinação de recursos orçamentários e financeiros capazes de atender as necessidades de articulação e equipamento para as Forças Armadas, por meio da Lei Orçamentária Anual, no patamar de 2% do PIB.\n**Mensagem (CN) n° 9, de 202010/12/2021 - CCAI - Recebido Relatório do Dep Cláudio Cajado: \n - Há de se considerar a possibilidade do aumento desse percentual, de forma gradativa, na base de um incremento anual de 0,1%, durante seis anos, até alcançarmos o patamar de 2%.\n - Na busca da destinação de 2% do PIB para a Defesa Nacional e do estabelecimento de mecanismos que previnam contingenciamentos e cortes nos recursos estinados aos projetos estratégicos, o Congresso Nacional assume especial relevo. No caso específico dos projetos estratégicos, há de se considerar a edição de uma Proposta de Emenda à Constituição prevenindo contingenciamentos e cortes .","status":"normal","assessor":"","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2326704&fichaAmigavel=nao"},{"proposicao":"4406/2021","tipo":"PL","casa":"CD","ementa":"Altera a Lei nº 3.765, de 4 de maio de 1960, que dispõe sobre as pensões militares.","autor":"Dep Helder Salomão - PT/ES , Vivi Reis - PSOL/PA e Paulo Teixeira - PT/SP","relator":"","impacto":"","tramitacao":"MESA: 20/02/2022 - Apense-se à(ao) PL-3132/2021.\nCREDN: 16/02/2022 - Recebimento\nCPASF:\nCFT:\nCCJC:","atuacao":"Acompanhar.","percepcao":"Perda da pensão militar, concernentes ao pensionista habilitado na condição de solteiro, viúvo ou divorciado, que venha a contrair matrimônio ou a constituir união estável, ou que venha a completar 45 (quarenta e cinco anos). \nDesignado assessor: Ten Cel CURVO","status":"normal","assessor":"Ten Cel CURVO","link":""},{"proposicao":"3132/2021","tipo":"PL","casa":"CD","ementa":"Regulamenta a pensão das filhas de militares.","autor":"Dep Darci de Matos - PSD/SC","relator":"Dep. Celso Russomanno","impacto":"","tramitacao":"MESA: 20/02/2022 - Apense-se à(ao) PL-4406/2021.\nCREDN: 03/05/2023 - Designado Relator, Dep. Celso Russomanno (REP/SP)\nEncerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 05/05/2023 a 17/05/2023). Não foram apresentadas emendas.\nCPASF:\nCFT:\nCCJC:","atuacao":"Acompanhar.","percepcao":"Majoração da alíquota de 3% (recalcular anualmente) referente à contribuição de pensão de militar cuja as filhas sejam beneficiárias ou a renúncia da contribuição da pensão.\nDesignado assessor: Ten Cel CURVO","status":"normal","assessor":"Ten Cel CURVO","link":""},{"proposicao":"2721/2021","tipo":"PL","casa":"SF","ementa":"Identifica, nos termos do § 11 do art. 37 da Constituição Federal, as parcelas não sujeitas ao limite remuneratório previsto no inciso XI do caput e nos §§ 9º e 12 do art. 37 da Constituição Federal; e dá outras providências.","autor":"CD","relator":"","impacto":"","tramitacao":"CCJ: aguardando designação de relator, 06/08/2021.\n07/06/2023 - Nota Técnica da Associação Nacional dos Magistrados da Justiça do Trabalho (Anamatra), com manifestação sobre a matéria (Parcela mensal de valorização do tempo de exercício da magistratura e do ministério público).\nPLEN:","atuacao":"Acompanhar.","percepcao":"Altera a indenização de transferência para reserva remunerada, entre outros pontos.\nDesignado assessor: Cap MARLON","status":"normal","assessor":"Cap MARLON","link":""},{"proposicao":"1409/2021","tipo":"PL","casa":"CD","ementa":"Eleva o valor do Auxílio Emergencial 2021 para R$ 600,00 (seiscentos reais); regulamenta o art. 107 do Ato das Disposições Constitucionais Transitórias (ADCT), para incluir as despesas tributárias no limite de despesas; revisa políticas públicas voltadas a cidadãos mais bem posicionados na distribuição de renda.","autor":"Dep Tabata Amaral - PDT/SP","relator":"","impacto":"","tramitacao":"CASP: Recebimento em 04/04/2023\nCPASF:\nCFT:\nCCJC:","atuacao":"Acompanhar.","percepcao":"Equipara as pensões militares ao RGPS ou ao RPPS.\nDesignado assessor: Cap ERICA","status":"normal","assessor":"Cap ERICA","link":""},{"proposicao":"1/022021","tipo":"PRN","casa":"CN","ementa":"Dispõe sobre o rito especial de tramitação para a apreciação do Congresso Nacional sobre a Política de Defesa Nacional, a Estratégia Nacional de Defesa e o Livro Branco de Defesa Nacional, de que trata o art. 9º da Lei Complementar nº 97, de 9 de junho de 1999.","autor":"Sen Fernando Collor (PROS/AL)","relator":"","impacto":"","tramitacao":"MESA: 21/12/2022 - A proposição continua a tramitar, nos termos do art. 332 do Regimento Interno","atuacao":"Acompanhar.","percepcao":"Proposta de um rito especial de tramitação para a apreciação do CN sobre a PDN, a END e o Livro Branco de Defesa Nacional, a fim de dar celeridade.\nDesignado assessor: Cap MARLON","status":"normal","assessor":"Cap MARLON","link":""},{"proposicao":"244/2020","tipo":"PLP","casa":"CD","ementa":"Concede isonomia tributária à indústria nacional para aquisições de produtos e serviços efetuadas pelas Forças de Defesa e Segurança Pública no Brasil.","autor":"Dep Luiz Philippe de Orleans e Bragança - PSL/SP , Bibo Nunes - PSL/RS , Dra. Soraya Manato - PSL/ES e outros","relator":"Dep. Eduardo Cury","impacto":"","tramitacao":"31/01/2023 - CFT: (Fim de Legislatura) O Relator, Dep. Eduardo Cury, deixou de ser membro da Comissão.","atuacao":"Acompanhar.","percepcao":"Propões a conecssão de isonomia tributária à indústria nacional para aquisições de produtos e serviços efetuadas pelas Forças de Defesa e Segurança Pública no Brasil.\nDesignado assessor: Cap TATIANA","status":"normal","assessor":"Cap TATIANA","link":""},{"proposicao":"2042/2020","tipo":"PL","casa":"CD","ementa":"Cria o Fundo Nacional de Combate a Epidemias e Pandemias.","autor":"Dep Dr. Leonardo - SOLIDARI/MT","relator":"","impacto":"","tramitacao":"Apensado ao PL 1022/2020.\nCSAUDE: aguardando designação do relator, 31/01/2023.\nCSAUDE: 13/09/2023 - Aprovado o Parecer do relator, Dep Léo Prates (PDT/BA). \nCFT: 14/09/2023 - Recebimento com seus apensados.\nCCJC:","atuacao":"Atuar na CFT para retirar a totalidade dos Fundos ligados à Defesa Nacional da composição das receitas do Fundo Nacional de Apoio a Pandemias e Epidemias (FNAPE)","percepcao":"Aprovado na CSAU o parecer do relator, com o seguinte texto: \n\"Art. 2º Constituem receitas do Fundo Nacional de Apoio a Pandemias e Epidemias - FNAPE:\nII - recursos provenientes da captação imediata de 10% (dez por cento) do patrimônio líquido de todos os Fundos Públicos existentes no país, exceto os saldos decorrentes do esforço de arrecadação dos servidores civis e militares da União;\nParágrafo único. As fontes especificadas nos incisos II, VI, VII, VIII e IX, deste artigo apenas serão incorporadas Fundo Nacional de Apoio a Pandemias e Epidemias - FNAPE durante o período em que o órgão gestor federal do Sistema Único de Saúde (SUS) declarar situação de emergência em saúde pública no território nacional.\"\nDesignado Assessor: Cap ERICA","status":"normal","assessor":"","link":""},{"proposicao":"1022/2020","tipo":"PL","casa":"CD","ementa":"Cria o Fundo Nacional de Apoio a Epidemias e Pandemias.","autor":"Mário Negromonte Jr. - PP/BA","relator":"Dep. Fernando Monteiro","impacto":"","tramitacao":"Apensados: PL 1033/2020 , PL 1100/2020 , PL 1238/2020 , PL 2042/2020 , PL 2749/2020 , PL 982/2021.\nCSAUDE: 13/09/2023 - Aprovado o Parecer do relator, Dep Léo Prates (PDT/BA). \nCFT: 14/09/2023 - Recebimento com seus apensados.\nCFT: 15/12/2023 - Designado Relator, Dep. Fernando Monteiro (PP-PE)\n18/12/2023 - Prazo para Emendas ao Projeto (5 sessões a partir de 19/12/2023)\n13/03/2024 - Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 18/12/2023 a 13/03/2024). Não foram apresentadas emendas.\nCCJC:","atuacao":"Atuar na CFT para retirar a totalidade dos Fundos ligados à Defesa Nacional da composição das receitas do Fundo Nacional de Apoio a Pandemias e Epidemias (FNAPE)","percepcao":"Aprovado na CSAU o parecer do relator, com o seguinte texto: \n\"Art. 2º Constituem receitas do Fundo Nacional de Apoio a Pandemias e Epidemias - FNAPE:\nII - recursos provenientes da captação imediata de 10% (dez por cento) do patrimônio líquido de todos os Fundos Públicos existentes no país, exceto os saldos decorrentes do esforço de arrecadação dos servidores civis e militares da União;\nParágrafo único. As fontes especificadas nos incisos II, VI, VII, VIII e IX, deste artigo apenas serão incorporadas Fundo Nacional de Apoio a Pandemias e Epidemias - FNAPE durante o período em que o órgão gestor federal do Sistema Único de Saúde (SUS) declarar situação de emergência em saúde pública no território nacional.\"\nDesignado Assessor: Cap TATIANA","status":"normal","assessor":"","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2242047"},{"proposicao":"137/2020","tipo":"PLP","casa":"SF","ementa":"Cria fonte de recursos para o enfrentamento de calamidade pública nacional decorrente de Pandemia da Covid-19 reconhecida pelo Congresso Nacional.","autor":"Mauro Benevides Filho - PDT/CE e André Figueiredo - PDT/CE","relator":"Dep. Elmar Nascimento","impacto":"","tramitacao":"Tramitação Câmara dos Deputados\nPLEN: aprovada o parecer do Relator, Dep. Elmar Nascimento (DEM-BA), \nDesignado Relator, favorável, na forma do substitutivo, 07/12/2020\nTramitação Senado Federal\nCAE: aguardando designação de relator, 02/02/2023.\nPLEN: 31/10/2023 - Encaminhado à publicação o Of nº 39, de 2023, da CAE, comunicando a prejudicialidade de proposições. A Presidência declara prejudicada a presente matéria, nos termos no art. 334, I, do Regimento Interno. A matéria vai ao arquivo.","atuacao":"Acompanhar.","percepcao":"Utilização dos fundos vinculados ao Ministério da Defesa.\nDesignado assessor: Cap TATIANA","status":"normal","assessor":"Cap TATIANA","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/146108"},{"proposicao":"102/2020","tipo":"PLP","casa":"CD","ementa":"Institui empréstimo compulsório sobre saldos financeiros dos fundos públicos federais para aplicações em programas de saúde, assistência social e de manutenção e geração de emprego e renda em decorrência da pandemia de COVID-19.","autor":"Renildo Calheiros - PCdoB/PE e outros","relator":"Dep. Fernando Rodolfo","impacto":"","tramitacao":"CPASF: designada relatora, Dep. Detinha (PL/MA), 11/04/2023.\n25/04/2023: Devolvida pelo Relator sem Manifestação.\n19/05/2023: Designado Relator, Dep. Fernando Rodolfo (PL-PE)\n07/06/2023: Apresenado REQ n. 1906/2023, Dep Laura Carneiro (PSD/RJ), que Requer a declaração de prejudicialidade de proposições relativas à pandemia de COVID-19, que tramitam nesta CPASF.\nMesa Diretora: 07/07/2023 - Arquivado.","atuacao":"Acompanhar.","percepcao":"Utilização dos fundos vinculados ao Ministério da Defesa.","status":"normal","assessor":"","link":""},{"proposicao":"51/2020","tipo":"PLP","casa":"SF","ementa":"Autoriza a utilização do superávit dos Fundos Públicos da União em políticas públicas de proteção aos trabalhadores e pequenos empreendedores informais e, para a ampliação de outros programas sociais, durante o estado de calamidade pública reconhecido pelo Decreto Legislativo nº 6, de 20 de março de 2020, provocada pelo Covid-19. (ARQUIVADO em 11/05/2023)","autor":"Senadora Eliziane Gama (CIDADANIA/MA)","relator":"","impacto":"","tramitacao":"PLEN: recedido, 26/03/2020.\nPLEN: 11/05/2023 - A Presidência declara prejudicado, nos termos do art. 334, I, do Regimento Interno, o Projeto.\nÚltimo local: 24/05/2023 - Coordenação de Arquivo\nA matéria vai ao Arquivo.","atuacao":"Acompanhar.","percepcao":"Utilização dos fundos vinculados ao Ministério da Defesa.","status":"normal","assessor":"","link":""},{"proposicao":"5750/2019","tipo":"PL","casa":"CD","ementa":"Altera o inciso I e cria o inciso VIII do §2º do Art. 2º da Lei nº 8.001, de 13 de março de 1990, que define os percentuais da distribuição da compensação financeira de que trata a Lei nº 7.990, de 28 de dezembro de 1989, e dá outras providências.","autor":"Deputado Aj Albuquerque (PP/CE)","relator":"","impacto":"","tramitacao":"Situação: Apensado ao PL 5235/2019","atuacao":"Acompanhar.","percepcao":"Altera o inciso I e cria o inciso VIII do §2º do Art. 2º da Lei nº 8.001,de 13 de março de 1990, passando a destinar 2% (dois por cento) da Compensação Financeira pela Exploração de Recursos Minerais (CFEM) para o Ministério da Defesa, para operações de apoio das Forças Armadas em catástrofes ambientais e humanitárias no território brasileiro.\nDesignado assessor: Cap TATIANA","status":"normal","assessor":"Cap TATIANA","link":"https://www.camara.leg.br/propostas-legislativas/2227641"},{"proposicao":"5235/2019","tipo":"PL","casa":"CD","ementa":"Modifica a Lei nº 8.001, de 13 de março de 1990, para destinar parcela da Compensação Financeira pela Exploração de Recursos Minerais (CFEM) à aquisição de equipamentos e sistemas de defesa.","autor":"Luiz Philippe de Orleans e Bragança (PL/SP) e outros.","relator":"","impacto":"","tramitacao":"10/05/2024 - CMADS: Dep. Zé Vitor (PL-MG)\n13/05/2024 - CMADS: Reabertura do Prazo para Emendas (5 sessões a partir de 14/05/2024).\n23/05/2024 - Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto. Não foram apresentadas emendas.","atuacao":"Acompanhar.","percepcao":"Modifica o § 2º do art. 2º da Lei nº 8.001, de 13 de março de 1990, criando o inciso I-A, passando a destinar 3,2% (três inteiros e dois décimos por cento) da Compensação Financeira pela Exploração de Recursos Minerais (CFEM) para o Ministério da Defesa, a serem aplicados na aquisição, manutenção e desenvolvimento de produtos estratégicos de defesa.\nDesignado assessor: Cap TATIANA","status":"normal","assessor":"Cap TATIANA","link":"https://www.camara.leg.br/proposicoesWeb/fichadetramitacao?idProposicao=2221920"},{"proposicao":"187/2019","tipo":"PEC","casa":"SF","ementa":"Institui reserva de lei complementar para criar fundos públicos e extingue aqueles que não forem ratificados até o final do segundo exercício financeiro subsequente à promulgação desta Emenda Constitucional, e dá outras providências.","autor":"Senador Fernando Bezerra Coelho (MDB/PE) e outros.","relator":"","impacto":"","tramitacao":"06/11/2019 - CCJ: Distribuído ao Senador Otto Alencar, para emitir relatório.\n04/03/2020 - CCJ: APROVADO PARECER NA COMISSÃO.\n15/04/2020 - SF-SLSF - Completada o número mínimo de assinaturas da Emenda nº 74, do Sen Eduardo Braga e outros Senador (excepcionalizar Fundos vinculados ao Ministério da Defesa e às Forças Armadas).\n21/12/2022 - Plenário do Senado Federal: A proposição continua a tramitar, nos termos do art. 332 do Regimento Interno.","atuacao":"Acompanhar.","percepcao":"\"PEC da Revisão dos Fundos\". Estabelece que a instituição de fundos públicos exige lei complementar e, em relação aos já existentes, obriga que sejam ratificados pelos respectivos Poderes Legislativos, por meio de Lei Complementar específica para cada um dos fundos públicos, até o final do segundo exercício financeiro subsequente à data da promulgação desta Emenda Constitucional, sob pena de extinção do fundo e transferência do respectivo patrimônio para o Poder ao qual ele se vinculava.\nO Fundo do Exército foi criado pela Lei nº 8.239, de 4 de outubro de 1991. Portanto, sim, ele foi criado até 31 de dezembro de 2016.\nDentro do contexto da PEC nº 187, de 2019, isso significa que o Fundo do Exército estaria entre os fundos que precisariam ser ratificados por lei complementar até o final do segundo exercício financeiro subsequente à promulgação da Emenda Constitucional para não serem extintos, a menos que haja outras disposições específicas ou exceções.\nDesignado assessor: Ten Cel ALESSANDRA","status":"normal","assessor":"Ten Cel ALESSANDRA","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/139703"},{"proposicao":"110/2019","tipo":"PEC","casa":"SF","ementa":"Altera o Sistema Tributário Nacional e dá outras providências.","autor":"Senador Davi Alcolumbre (UNIÃO/AP)","relator":"","impacto":"","tramitacao":"CCJ: aguardando designação de relator, 02/02/2023.\n08/08/2023 - A Presidência do Senado determina tramitação conjunta da PEC nº 45/2019, com as PEC nºs 110/2019 e 46/2022, por tratarem de tema correlato.\n08/11/2023 SF-SEADI - Secretaria de Atas e Diários: PREJUDICADA. A matéria vai ao arquivo.","atuacao":"Acompanhar.","percepcao":"- Em substituição ao RETID, foi incluído o seguinte texto:\n\"Art. 9º A lei complementar que instituir o imposto de que trata o art. 156-A e a contribuição de que trata o art. 195, V, ambos da Constituição Federal, poderá prever os regimes diferenciados de tributação de que trata este artigo, desde que sejam uniformes em todo o território nacional e sejam realizados os respectivos ajustes nas alíquotas de referência com vistas a reequilibrar a arrecadação da esfera federativa.\n§ 1º A lei complementar definirá as operações beneficiadas com redução de 60% (sessenta por cento) das alíquotas dos tributos de que trata o caput entre as relativas aos seguintes bens e serviços:\nXIIII – bens e serviços relacionados a soberania e segurança nacional, segurança da informação e segurança cibernética;\"\n- Designada assessora: Ten Cel ALESSANDRA.","status":"normal","assessor":"","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/137699"},{"proposicao":"45/2019","tipo":"PEC","casa":"CD","ementa":"Altera o Sistema Tributário Nacional e dá outras providências.","autor":"Deputado Baleia Rossi\n (MDB-SP)","relator":"","impacto":"","tramitacao":"07/07/2023 - Plenário CD: Aprovada a Redação Final. A matéria vai ao Senado Federal (PEC 45-F/2019).\n08/11/2023 - Plenário SF: Aprovada a matéria, retorna à Câmara dos Deputados. A PEC 110/2019 e a PEC 46/2022, prejudicadas, vão ao Arquivo.\n14/11/2023 - Mesa Diretora da CD: Recebido o Of nº 1140/2023 do SF, que submete à apreciação da CD, o Substitutivo do Senado à PEC n° 45, de 2019, que \"Altera o Sistema Tributário Nacional\".","atuacao":"Acompanhar.","percepcao":"- Em substituição ao RETID, foi incluído o seguinte texto:\n\"Art. 9º A lei complementar que instituir o imposto de que trata o art. 156-A e a contribuição de que trata o art. 195, V, ambos da Constituição Federal, poderá prever os regimes diferenciados de tributação de que trata este artigo, desde que sejam uniformes em todo o território nacional e sejam realizados os respectivos ajustes nas alíquotas de referência com vistas a reequilibrar a arrecadação da esfera federativa.\n§ 1º A lei complementar definirá as operações beneficiadas com redução de 60% (sessenta por cento) das alíquotas dos tributos de que trata o caput entre as relativas aos seguintes bens e serviços:\nXIIII – bens e serviços relacionados a soberania e segurança nacional, segurança da informação e segurança cibernética;\"\n- Designada assessora: Ten Cel ALESSANDRA.","status":"normal","assessor":"","link":"https://www25.senado.leg.br/web/atividade/materias/-/materia/158930"},{"proposicao":"295/2016","tipo":"PLP","casa":"CD","ementa":"Estabelece, com amparo nos arts. 163 e 165, § 9º, da Constituição Federal, normas gerais sobre planejamento, orçamento, fundos, contabilidade, controle e avaliação na administração pública; altera a Lei Complementar nº 101, de 4 de maio de 2000; e revoga a Lei nº 4.320, de 17 de março de 1964.","autor":"Senado Federal - Tasso Jereissati (PSDB-CE)","relator":"","impacto":"","tramitacao":"Origem: PLS 229/2009\nMesa Diretora: 21/06/2016 - Recebido do Senado para revisão da CD.\nMesa Diretora: 24/03/2022 - Apense-se à(ao) PLP-25/2022.\nMesa Diretora: 02/06/2023 - Apense-se à(ao) PLP-62/2023.","atuacao":"Acompanhar.","percepcao":"Proposta de Nova Lei Complementar de Finanças Públicas.","status":"normal","assessor":"","link":""},{"proposicao":"1826/2022","tipo":"PL","casa":"CD","ementa":"Concede Auxílio-Especial a ex-militares do Exército Brasileiro que, no ano de 1967, integrando o 20º Contingente do Batalhão Suez, no serviço ativo e em Missão de Paz no exterior, participaram da Guerra dos Seis Dias, no Oriente Médio.","autor":"Bibo Nunes - PL/RS","relator":"Dep. Arlindo Chinaglia","impacto":"","tramitacao":"CREDN: aprovado o Parecer do Relator, Dep. Arlindo Chinaglia (PT-SP), pela aprovação, 22/04/2015.\nCPASF: aprovado o Parecer da Relatora, Dep. Jandira Feghali (PCdoB-RJ), pela aprovação, 10/06/2015.\nCFT: aprovado o Parecer do relator, Dep. Otavio Leite, pela compatibilidade e adequação financeira e orçamentária, 03/12/2015.\nCCJC: aprovado o Parecer do Relator, Dep. Valtenir Pereira (PMB-MT), pela constitucionalidade, juridicidade e técnica legislativa, 08/12/2015.\nPLEN:\n\nApensada ao PL 8254/2014.","atuacao":"","percepcao":"Busca proporcionar uma reparação aos 427 militares do 20° Contingente, tanto para os de carreira (oficiais e sargentos) quanto para os temporários (cabos e soldados).\nDesignado assessor: Ten Cel MONTEIRO","status":"normal","assessor":"Ten Cel MONTEIRO","link":""},{"proposicao":"1588/2019","tipo":"PL","casa":"CD","ementa":"Altera a redação do art. 45, da Lei nº 8.080, de 19 de setembro de 1990, para prever o atendimento pelos serviços de saúde das Forças Armadas aos seringueiros que, entre 1943 e 1945, foram alistados pelo Serviço Especial de \nMobilização de Trabalhadores para a Amazônia - SEMTA com objetivo de extrair borracha na Amazônia, como parte do esforço de guerra brasileiro, durante a Segunda Guerra Mundial.","autor":"Mauro Nazif - PSB/RO","relator":"Dep. Jesus Sérgio","impacto":"","tramitacao":"CINDRE: aprovado o Parecer do Relator, Dep. Jesus Sérgio (PDT-AC), pela aprovação, 14/08/2019.\nCREDN: aguardando designação de relator, 31/03/2023.\nCFT:\nCCJC:","atuacao":"","percepcao":"Utilização do Sistema de Saúde das Forças Armadas.\nDesignado assessor: Cel BANDEIRA","status":"normal","assessor":"Cel BANDEIRA","link":""},{"proposicao":"2842/2020","tipo":"PL","casa":"CD","ementa":"Permite a utilização de hospitais militares para o atendimento da população em geral durante a pandemia do COVID-19.","autor":"Helder Salomão - PT/ES","relator":"","impacto":"","tramitacao":"CREDN: aguardando designação de relator, 31/01/2023.\nCPASF:\nCCJC:","atuacao":"","percepcao":"Estabelece que os leitos disponíveis de Terapia Intensiva e Semi-Intensiva dos hospitais militares serão disponibilizados através do SUS, constando de lista única. \nDesignado assessor: Cel BANDEIRA","status":"normal","assessor":"Cel BANDEIRA","link":""},{"proposicao":"457/2021","tipo":"PL","casa":"CD","ementa":"Altera a Lei nº 13.979, de 6 de fevereiro de 2020, que dispõe sobre as medidas de enfrentamento da emergência de saúde pública decorrente do coronavírus (Covid-19), para possibilitar a utilização temporária de leitos vagos, nos Hospitais das Forças Armadas, pela população civil.","autor":"Eduardo Bismarck - PDT/CE","relator":"","impacto":"","tramitacao":"CREDN:\nCPASF:\nCCJC:\nPLEN: Matéria não apreciada em face do encerramento da Sessão, 07/07/2021.","atuacao":"","percepcao":"Utilização do Sistema de Saúde das Forças Armadas.\nDesignado assessor: Cel BANDEIRA","status":"normal","assessor":"Cel BANDEIRA","link":""},{"proposicao":"2911/2022","tipo":"PL","casa":"CD","ementa":"Autoriza o Poder Executivo federal, por meio do Ministério da Defesa, a doar uma passadeira flutuante de alumínio, do Comando do Exército, para a República do Paraguai.","autor":"Poder Executivo","relator":"","impacto":"","tramitacao":"MERCOSUL: recebida, 13/03/2023.\nCASP:\nCCJC:","atuacao":"","percepcao":"Designado assessor: Cel ANDERSON","status":"normal","assessor":"Cel ANDERSON","link":""},{"proposicao":"453/2017","tipo":"PLP","casa":"CD","ementa":"Altera a Lei Complementar Nº 97, de 9 de junho de 1999, atribuindo ao Exército a execução de obras e serviços de engenharia sem necessidade de licitação pública nos casos que especifica.","autor":"Gonzaga Patriota - PSB/PE","relator":"Dep. Hugo Leal","impacto":"","tramitacao":"CREDN: Aprovado o Parecer do Relator, Dep. Hugo Leal (PSD-RJ), com Emenda, 25/09/2019.\nCFT: apresentação do Parecer do Relator, Dep. Elias Vaz (PSB-GO), pela não implicação da matéria em aumento ou diminuição da receita ou da despesa públicas, não cabendo pronunciamento quanto à adequação financeira e orçamentária do Projeto de Lei Complementar nº 453/2017, e da Emenda Adotada pela Comissão Relações Exteriores e Defesa Nacional, 19/10/2021.\nCCJC: recebido, 15/12/2022.","atuacao":"","percepcao":"Alterar a Lei Complementar nº 97, de 9 de junho de 1999 (que dispõe sobre as normas gerais para a organização, o preparo e o emprego das Forças Armadas), especificamente para modificar a redação do inciso II do art. 17-¬A e lhe acrescentar alíneas, com vistas a permitir que o Exército Brasileiro execute preferencialmente obras e serviços de engenharia, sem necessidade de licitação, nos casos em que especifica.","status":"normal","assessor":"","link":""},{"proposicao":"3887/2020","tipo":"PL","casa":"CD","ementa":"Institui a Contribuição Social sobre Operações com Bens e Serviços - CBS, \ne altera a legislação tributária federal.","autor":"Poder Executivo","relator":"","impacto":"","tramitacao":"Aguardando Criação de Comissão \nTemporária.","atuacao":"","percepcao":"Institui a contribuição social sobre operações de bens e serviços.","status":"normal","assessor":"","link":""}];
